	//从一个map中取值时，可选第二个返回值是这个键是否存在于map中
	//这个可以用来消除键不存在或键有零值产生的歧义
	_, prs := m[&quot;k2&quot;]
	fmt.Println(&quot;prs: &quot;, prs)
	//一行申明和初始化一个map
	n := map[string]int{&quot;foo&quot;: 1, &quot;bar&quot;: 2, &quot;zhang&quot;: 3}
	fmt.Println(n)
}

golang/基础/go-基础-05---字符串与字符处理.content:
Go 基础 05 - 字符串与字符处理
字符串特性
s := &quot;Hello, 世界&quot;
Go 中的 string：

不可变 — 创建后不能修改（类似 Java）
UTF-8 编码 — 每个字符 1-4 字节
底层结构 — 指向只读内存区域的指针 + 长度
零值 — &quot;&quot;（不是 nil）

strings 包常用函数
import &quot;strings&quot;

s := &quot;Hello, World!&quot;

strings.Contains(s, &quot;World&quot;)       // true
strings.HasPrefix(s, &quot;Hello&quot;)      // true
strings.HasSuffix(s, &quot;!&quot;)          // true
strings.Index(s, &quot;o&quot;)              // 4（第一个匹配位置）
strings.LastIndex(s, &quot;o&quot;)          // 8（最后一个匹配位置）
strings.Count(s, &quot;l&quot;)              // 3

// 大小写转换
strings.ToUpper(s)                 // &quot;HELLO, WORLD!&quot;
strings.ToLower(s)                 // &quot;hello, world!&quot;
strings.Title(&quot;hello world&quot;)       // &quot;Hello World&quot;（已弃用，改用 cases.Title）

// 分割与连接
parts := strings.Split(&quot;a,b,c&quot;, &quot;,&quot;)      // [&quot;a&quot;, &quot;b&quot;, &quot;c&quot;]
joined := strings.Join(parts, &quot;-&quot;)        // &quot;a-b-c&quot;
fields := strings.Fields(&quot; a  b   c &quot;)    // [&quot;a&quot;, &quot;b&quot;, &quot;c&quot;]（按空白分割）

// 修剪
strings.Trim(&quot;!!Hello!!&quot;, &quot;!&quot;)            // &quot;Hello&quot;
strings.TrimSpace(&quot;  Hello  &quot;)            // &quot;Hello&quot;
strings.TrimPrefix(&quot;/api/v1&quot;, &quot;/api&quot;)     // &quot;/v1&quot;

// 替换
strings.Replace(&quot;oink oink&quot;, &quot;o&quot;, &quot;e&quot;, 1) // &quot;eink oink&quot;（1次）
strings.ReplaceAll(&quot;oink oink&quot;, &quot;o&quot;, &quot;e&quot;) // &quot;eink eink&quot;（全部）
strings.Repeat(&quot;na&quot;, 3)                   // &quot;nanana&quot;

// 比较
strings.Compare(&quot;a&quot;, &quot;b&quot;)                 // -1（字典序）
strings.EqualFold(&quot;Go&quot;, &quot;go&quot;)              // true（忽略大小写）
strings.Builder — 高效字符串拼接
避免 + 拼接产生大量临时对象：
var sb strings.Builder
sb.Grow(100)               // 预分配内存

sb.WriteString(&quot;Hello&quot;)
sb.WriteByte(&#039;,&#039;)
sb.WriteString(&quot; World&quot;)
sb.WriteRune(&#039;!&#039;)

result := sb.String()      // &quot;Hello, World!&quot;

strings.Builder 比 + 或 fmt.Sprintf 高效得多，适合循环拼接。

strings.Reader — 高效读取
r := strings.NewReader(&quot;Hello, World!&quot;)
buf := make([]byte, 5)
r.Read(buf)                // buf = &quot;Hello&quot;
r.Read(buf)                // buf = &quot;, Wo&quot;
格式化字符串
import &quot;fmt&quot;

// 拼接
s := fmt.Sprintf(&quot;Hello, %s! You are %d years old.&quot;, &quot;Alice&quot;, 30)

// 数字格式化
fmt.Sprintf(&quot;%d&quot;, 255)               // &quot;255&quot;
fmt.Sprintf(&quot;%08b&quot;, 255)             // &quot;11111111&quot;（二进制）
fmt.Sprintf(&quot;%x&quot;, 255)               // &quot;ff&quot;（十六进制）
fmt.Sprintf(&quot;%.2f&quot;, 3.14159)         // &quot;3.14&quot;
算法：最长不重复子串
func lengthOfNonRepeatingSubStr(s string) int {
    lastOccurred := make(map[rune]int)
    start := 0
    maxLength := 0

    for i, ch := range []rune(s) {
        if lastIdx, ok := lastOccurred[ch]; ok &amp;&amp; lastIdx &gt;= start {
            start = lastIdx + 1
        }
        if i-start+1 &gt; maxLength {
            maxLength = i - start + 1
        }
        lastOccurred[ch] = i
    }
    return maxLength
}
