golang/基础/go-基础-21---fmt-格式化输出.content:
Go 基础 21 - fmt 格式化输出
三大输出函数

























函数作用换行fmt.Print输出到标准输出❌ 不换行fmt.Println输出到标准输出✅ 自动换行，参数间加空格fmt.Printf格式化输出❌ 需手动加 \n
name := &quot;Alice&quot;
age := 30

fmt.Print(&quot;Hello&quot;)                          // &quot;Hello&quot;
fmt.Println(&quot;Hello&quot;, &quot;World&quot;)               // &quot;Hello World\n&quot;
fmt.Printf(&quot;Name: %s, Age: %d\n&quot;, name, age) // &quot;Name: Alice, Age: 30&quot;
写入字符串
s := fmt.Sprintf(&quot;Name: %s, Age: %d&quot;, name, age)
// s = &quot;Name: Alice, Age: 30&quot;
写入 io.Writer
var buf bytes.Buffer
fmt.Fprintf(&amp;buf, &quot;Name: %s&quot;, name)
fmt.Fprintln(&amp;buf, &quot;extra&quot;)     // 追加 + 换行
常用格式化动词
通用



































动词作用示例%v默认格式fmt.Sprintf(&quot;%v&quot;, 42) → &quot;42&quot;%+v带字段名的结构体{Name:Alice Age:30}%#vGo 语法表示main.Person{Name:&quot;Alice&quot;, Age:30}%T类型string、int%%百分号字面量&quot;%&quot;
整数


















































动词作用示例（n=255）%d十进制&quot;255&quot;%b二进制&quot;11111111&quot;%o八进制&quot;377&quot;%x十六进制小写&quot;ff&quot;%X十六进制大写&quot;FF&quot;%c对应 Unicode 字符&#039;ÿ&#039;%q带引号的字符&#039;ÿ&#039;%UUnicode 格式U+00FF
浮点数






























动词作用示例（n=3.14159）%f固定小数位&quot;3.141590&quot;%.2f指定小数位&quot;3.14&quot;%e科学计数法&quot;3.141590e+00&quot;%g按需选择 %e 或 %f&quot;3.14159&quot;（去掉尾随零）
字符串








































动词作用示例%s字符串&quot;hello&quot;%q带引号字符串&quot;\&quot;hello\&quot;&quot;%x十六进制编码&quot;68656c6c6f&quot;%10s宽度 10（右对齐）&quot;     hello&quot;%-10s宽度 10（左对齐）&quot;hello     &quot;%.5s截断 5 个字符&quot;hello&quot;
宽度与精度
// 宽度与对齐
fmt.Printf(&quot;|%10s|&quot;, &quot;hello&quot;)    // &quot;|     hello|&quot;（宽度 10，右对齐）
fmt.Printf(&quot;|%-10s|&quot;, &quot;hello&quot;)   // &quot;|hello     |&quot;（宽度 10，左对齐）

// 精度
fmt.Printf(&quot;%.2f&quot;, 3.14159)      // &quot;3.14&quot;
fmt.Printf(&quot;%8.2f&quot;, 3.14159)     // &quot;    3.14&quot;（宽度 8，精度 2）

// 数字补零
fmt.Printf(&quot;%05d&quot;, 42)           // &quot;00042&quot;（宽度 5，补零）
结构体格式化
type Person struct {
    Name string
    Age  int
}

p := Person{&quot;Alice&quot;, 30}

fmt.Printf(&quot;%%v:  %v\n&quot;, p)    // {Alice 30}
fmt.Printf(&quot;%%+v: %+v\n&quot;, p)   // {Name:Alice Age:30}
fmt.Printf(&quot;%%#v: %#v\n&quot;, p)   // main.Person{Name:&quot;Alice&quot;, Age:30}
fmt.Printf(&quot;%%T:  %T\n&quot;, p)    // main.Person
错误格式化
// fmt.Errorf 创建格式化错误
err := fmt.Errorf(&quot;user %s not found&quot;, &quot;Alice&quot;)
// err.Error() = &quot;user Alice not found&quot;

// 错误链（Go 1.20+）
err = fmt.Errorf(&quot;login failed: %w&quot;, err)
// errors.Is(err, originalErr) // true
实现 Stringer 接口
自定义类型的默认格式化通过实现 String() 方法控制：
type Point struct{ X, Y int }

func (p Point) String() string {
    return fmt.Sprintf(&quot;(%d, %d)&quot;, p.X, p.Y)
}

p := Point{3, 4}
fmt.Println(p)          // &quot;(3, 4)&quot;（自动调用 String()）
fmt.Printf(&quot;%v&quot;, p)     // &quot;(3, 4)&quot;
fmt.Printf(&quot;%#v&quot;, p)    // &quot;main.Point{X:3, Y:4}&quot;（Stringer 不影响 %#v）
格式化注意事项
性能对比
// 慢：fmt.Sprintf（涉及反射）
result := fmt.Sprintf(&quot;%s-%d&quot;, name, age)

// 快：strings.Builder
var sb strings.Builder
sb.WriteString(name)
sb.WriteByte(&#039;-&#039;)
sb.WriteString(strconv.Itoa(age))

// 更快（已知容量时）
sb.Grow(len(name) + 1 + 10)  // 预分配
循环中避免反复格式化
// ❌ 慢：每次迭代都格式化
for _, v := range items {
    fmt.Printf(&quot;Item: %s\n&quot;, v)
}

// ✅ 快：用 strings.Builder 拼接后一次性输出
var sb strings.Builder
for _, v := range items {
    fmt.Fprintf(&amp;sb, &quot;Item: %s\n&quot;, v)
}
fmt.Print(sb.String())
参考资料

Go fmt 包文档
Go by Example: String Formatting
Effective Go: Formatting

