Go Instance 02
读取文件
案例1
读取文件的内容并显示在终端(带缓冲区的方式)
package main

import (
	&quot;bufio&quot;
	&quot;fmt&quot;
	&quot;io&quot;
	&quot;os&quot;
)
//读取文件的内容并显示在终端(带缓冲区的方式)
func main() {
	//打开文件
	file, err := os.Open(&quot;fileOperations/abc.txt&quot;)
	if err != nil {
		fmt.Println(&quot;文件打开失败&quot;)
	}
	//函数退出时关闭文件
	defer file.Close()
	//输出文件
	fmt.Printf(&quot;file=%v \n&quot;, &amp;file)
	//创建一个*Reader，带缓冲的，默认缓冲区大小为4096
	reader := bufio.NewReader(file)
	//循环读取文件内容
	for {
		//读到一个换行结束
		s, err := reader.ReadString(&#039;\n&#039;)
		//输出文件内容
		fmt.Print(s)
		//io.EOF表示文件末尾
		if err == io.EOF {
			fmt.Println()
			break
		}
	}
	fmt.Println(&quot;文件读取结束&quot;)
}
案例2
对于文件不太大的情况，可以使用ioutil一次将整个文件读到内存里
package main

import (
	&quot;fmt&quot;
	&quot;io/ioutil&quot;
)
//对于文件不太大的情况，可以使用ioutil一次将整个文件读到内存里
func main() {
	//打开文件
	file, err := ioutil.ReadFile(&quot;fileOperations/abc.txt&quot;)
	if err != nil {
		fmt.Println(&quot;open file err:&quot;, err)
	}
	//把读取到的文件显示在终端
	//不需要显式的Open和Close文件，因为这两个操作已经被封装在ioutilFile函数内部
	fmt.Printf(&quot;file is %v\n&quot;, file)
	fmt.Printf(&quot;file is %v\n&quot;, string(file))
}
写入文件
案例1
创建一个新文件写入5句hello
package main

import (
	&quot;bufio&quot;
	&quot;fmt&quot;
	&quot;os&quot;
)
//创建一个新文件写入5句hello
func main() {
	//打开文件，可写可创建
	file, err := os.OpenFile(&quot;fileOperations/write.txt&quot;, os.O_WRONLY|os.O_CREATE, 0666)
	if err != nil{
		fmt.Printf(&quot;open file err: %v\n&quot;, err)
	}
	//函数退出关闭文件
	defer file.Close()
	//写入文件，使用带缓存的*writer
	writer := bufio.NewWriter(file)
	for i := 0; i &lt; 5; i++ {
		writer.WriteString(&quot;hello\n&quot;)
	}
	//Flush将缓存的文件真正写入到文件中
	writer.Flush()
	fmt.Println(&quot;文件写入成功&quot;)
}
案例2
打开已有文件追加内容
package main

import (
	&quot;bufio&quot;
	&quot;fmt&quot;
	&quot;os&quot;
)
//打开已有文件追加内容
func main() {
	//打开文件，文件可写可以追加
	file, err := os.OpenFile(&quot;fileOperations/write.txt&quot;, os.O_APPEND|os.O_WRONLY, 0666)
	if err != nil {
		fmt.Println(&quot;file is err&quot;, err)
	}
	//函数最后关闭文件
	defer file.Close()
	//写入文件，使用带缓存的*writer
	writer := bufio.NewWriter(file)
	for i := 0; i &lt; 5; i++ {
		writer.WriteString(&quot;abc \r\n&quot;)
	}
	//Flush将缓存文件真正写入到文件中
	writer.Flush()
}
案例3
打开一个存在的文件读取内容并追加内容
package main

import (
	&quot;bufio&quot;
	&quot;fmt&quot;
	&quot;io&quot;
	&quot;os&quot;
)
//打开一个存在的文件读取内容并追加内容
func main() {
	//打开文件，可读可写可追加
	file, err := os.OpenFile(&quot;fileOperations/write.txt&quot;, os.O_APPEND|os.O_RDWR, 0666)
	if err != nil {
		fmt.Println(&quot;file open err:&quot;, err)
	}
	//函数结束关闭文件
	defer file.Close()
	//读取文件
	reader := bufio.NewReader(file)
	for{
		s, err := reader.ReadString(&#039;\n&#039;)
		fmt.Print(s)
		if err == io.EOF {
			break
		}
	}
	//写入文件
	writer := bufio.NewWriter(file)
	for i := 0; i &lt; 5; i++ {
		writer.WriteString(&quot;hello world\n&quot;)
	}
	writer.Flush()
}
案例4
将一个文件内容复制到另一个文件中
package main

import (
	&quot;fmt&quot;
	&quot;io/ioutil&quot;
	&quot;os&quot;
)
//将一个文件内容复制到另一个文件中
func main() {
	os.OpenFile(&quot;fileOperations/writecopy.txt&quot;, os.O_CREATE|os.O_WRONLY, 0666)
	file, err := ioutil.ReadFile(&quot;fileOperations/write.txt&quot;)
	if err != nil {
		fmt.Println(&quot;file1 open err:&quot;, err)
	}
	err = ioutil.WriteFile(&quot;fileOperations/writecopy.txt&quot;, file, 0666)
	if err != nil {
		fmt.Println(&quot;file2 copy err&quot;, err)
	}
}
拷贝文件
案例1
将一个图片拷贝到另一个文件下
package main

import (
	&quot;bufio&quot;
	&quot;fmt&quot;
	&quot;io&quot;
	&quot;os&quot;
)
//编写一个函数，传入两个文件路径
func copyFile(dstFile string, srcFile string) (written int64, err error) {
	//打开srcFile
	read, err := os.OpenFile(srcFile, os.O_RDONLY, 0)
	if err != nil {
		fmt.Println(&quot;srcFile open err:&quot;, err)
	}
	defer read.Close()
	//通过srcFile找到 reader
	reader := bufio.NewReader(read)
	//打开dstFile
	write, err := os.OpenFile(dstFile, os.O_WRONLY|os.O_CREATE, 0666)
	if err != nil {
		fmt.Println(&quot;dstFile open err:&quot;, err)
	}
	defer write.Close()
	//通过dstFile找到writer
	writer := bufio.NewWriter(write)

	return io.Copy(writer, reader)
}

func main() {
	//将srcFile文件拷贝到dstFile文件
	srcFile := &quot;F:/hugo-blog/cc/static/go7.jpg&quot;
	dstFile := &quot;D:/bgird.jpg&quot;
	//调用copyFile完成拷贝
	written, err := copyFile(dstFile, srcFile)
	if err != nil {
		fmt.Println(&quot;copy file err:&quot;, err)
	} else {
		fmt.Println(&quot;copy file success, written:&quot;, written)
	}
}

