Go Instance 03
字符操作
案例1
统计一个文本文件的字符个数
package main

import (
	&quot;bufio&quot;
	&quot;fmt&quot;
	&quot;io&quot;
	&quot;os&quot;
)
//定义一个结构体保存统计结果
type charCount struct {
	//英文个数
	chCount		int
	//空格个数
	spaceCount	int
	//数字个数
	numCount	int
	//其他个数
	otherCount	int
}

func main() {
	/**
	思路：打开一个文件，创建一个Reader
	每读取一行，统计字符保存到结构体中
	 */
	file, err := os.Open(&quot;fileOperations/abc.txt&quot;)
	if err != nil {
		fmt.Println(&quot;file open err:&quot;, err)
	}
	reader := bufio.NewReader(file)
	fileC := charCount{}
	//循环读取file内容
	for {
		s, err := reader.ReadString(&#039;\n&#039;)
		//为了兼容中文转化为rune
		for _, r := range []rune(s) {
			switch {
			case r &gt;= &#039;a&#039; &amp;&amp; r &lt;= &#039;z&#039;:
				fallthrough
			case r &gt;= &#039;A&#039; &amp;&amp; r &lt;= &#039;Z&#039;:
				fileC.chCount++
			case r &gt; &#039;0&#039; &amp;&amp; r &lt; &#039;9&#039;:
				fileC.numCount++
			case r == &#039; &#039; || r == &#039;\t&#039;:
				fileC.spaceCount++
			default:
				fileC.otherCount++
			}
		}
		if err == io.EOF {
			break
		}
	}

	fmt.Printf(&quot;file has chcount: %d, numcount: %d, spaceCount: %d, otherCount: %d&quot;, fileC.chCount, fileC.numCount, fileC.spaceCount, fileC.otherCount)
}
将数据序列化成json字符串
将数据(结构体，Map，Slice，基础数据类型)序列化成json字符串
json序列化是指将有key-value结构的数据类型(比如：结构体，Map，Slice)序列化成json字符串的操作
package main

import (
	&quot;encoding/json&quot;
	&quot;fmt&quot;
)

type Hero struct {
	Name	string	`json:&quot;hero_name&quot;`
	Age		int		`json:&quot;hero_age&quot;`
	Sex		string
}
//结构体序列化
func changeStruct() {
	hero := Hero{
		Name:	&quot;小陈&quot;,
		Age:	18,
		Sex:	&quot;男&quot;,
	}
	//将结构体序列化
	bytes, err := json.Marshal(hero)
	if err != nil{
		fmt.Println(&quot;json marshal fail:&quot;, err)
	}
	fmt.Printf(&quot;结构体序列化后的字段：%v\n&quot;, string(bytes))
}
//Map序列化
func changeMap() {
	map1 := make(map[string]interface{})
	map1[&quot;name&quot;] = &quot;张无忌&quot;
	map1[&quot;age&quot;] = 22
	map1[&quot;address&quot;] = &quot;冰火岛&quot;
	//将map序列化
	bytes, err := json.Marshal(map1)
	if err != nil {
		fmt.Println(&quot;json marshal fail:&quot;, err)
	}
	fmt.Printf(&quot;Map序列化后的字段：%v\n&quot;, string(bytes))
}
//Slice序列化
func changeSlice() {
	var slice []map[string]interface{}
	m1 := make(map[string]interface{})
	m1[&quot;name&quot;] = &quot;张无忌&quot;
	m1[&quot;age&quot;] = 25
	m1[&quot;address&quot;] = &quot;冰火岛&quot;
	slice = append(slice, m1)

	m2 := make(map[string]interface{})
	m2[&quot;name&quot;] = &quot;张三丰&quot;
	m2[&quot;age&quot;] = &quot;88&quot;
	m2[&quot;address&quot;] = []string{&quot;武当山&quot;, &quot;夏威夷&quot;}
	slice = append(slice, m2)
	//slice序列化
	bytes, err := json.Marshal(slice)
	if err != nil {
		fmt.Println(&quot;json marshal fail:&quot;, err)
	}
	fmt.Printf(&quot;Slice序列化后的字段：%v\n&quot;, string(bytes))
}
//基本类型序列化(对基础类型序列化意义不大)
func changeFloat() {
	var f float64 = 3.14
	//对float序列化
	bytes, err := json.Marshal(f)
	if err != nil {
		fmt.Println(&quot;json marshal fail:&quot;, err)
	}

	fmt.Println(&quot;Float序列化后的字段：&quot;, string(bytes))
}

func main() {
	changeStruct()
	changeMap()
	changeSlice()
	changeFloat()
}
将json字符串反序列化成对应数据
将json字符串 反序列化成对应数据（比如：结构体，map，切片）
package main

import (
	&quot;encoding/json&quot;
	&quot;fmt&quot;
)

type Hero struct {
	Name	string	`json:&quot;hero_name&quot;`
	Age		int		`json:&quot;hero_age&quot;`
	Sex		string
}
//将json字符串反序列化为结构体
func unmarshalStruct() {
	str := &quot;{\&quot;hero_name\&quot;:\&quot;小陈\&quot;,\&quot;hero_age\&quot;:18,\&quot;Sex\&quot;:\&quot;男\&quot;}&quot;

	var hero Hero

	err := json.Unmarshal([]byte(str), &amp;hero)
	if err != nil {
		fmt.Println(&quot;json unmarshal fail:&quot;, err)
	}
	fmt.Printf(&quot;json反序列化为结构体：%v\n&quot;, hero)
}
//将json字符串反序列化为Map
func unmarshalMap() {
	str := &quot;{\&quot;name\&quot;: \&quot;张无忌\&quot;,\&quot;age\&quot;: 22,\&quot;address\&quot;: \&quot;冰火岛\&quot;}&quot;
	//定义一个map，反序列化的时候不需要make，因为unmarshal封装了make
	var map1 map[string]interface{}

	err := json.Unmarshal([]byte(str), &amp;map1)

	if err != nil {
		fmt.Println(&quot;json unmarshal fail:&quot;, err)
	}
