}
//将json字符串反序列化为Slice
func unmarshalSlice() {
	str := &quot;[{\&quot;address\&quot;:\&quot;冰火岛\&quot;,\&quot;age\&quot;:25,\&quot;name\&quot;:\&quot;张无忌\&quot;},{\&quot;address\&quot;:[\&quot;武当山\&quot;,\&quot;夏威夷\&quot;],\&quot;age\&quot;:\&quot;88\&quot;,\&quot;name\&quot;:\&quot;张三丰\&quot;}]&quot;
	//定义一个slice，反序列化的时候不需要make，因为unmarshal封装了make
	var slice []map[string]interface{}

