golang/实战/go-实战-04---instance.content:
Go Instance 04
goroutine和channel
goroutine和channel协同工作
具体要求

开启一个writeData协程，向管道intChan中写入50个整数
开启一个readData协程，从管道intChan中读取writeData写入的数据
注意writeData和readData操作的是同一个管道
主线程需要等待writeData和readData协程都完成工作才能退出管道

思路分析

思路分析
package main

import &quot;fmt&quot;

func writeData(intChan chan int)  {
	for i := 1; i &lt;= 50; i++ {
		intChan &lt;-i
		fmt.Println(&quot;write:&quot;, i)
	}
	close(intChan)
}

func readData(intChan chan int, exitChan chan bool)  {
	for {
		n, ok := &lt;-intChan
		if !ok {
			break
		}
		fmt.Println(&quot;read:&quot;, n)
	}
	exitChan &lt;- true
	close(exitChan)
}

func main() {
	intChan := make(chan int, 50)
	exitChan := make(chan bool, 1)

	go writeData(intChan)
	go readData(intChan, exitChan)

	for {
		_, ok := &lt;-exitChan
		if !ok {
			break
		}
	}
}
读和写频率不一样也没有问题
package main

import (
	&quot;fmt&quot;
	&quot;time&quot;
)

func writeData(intChan chan int)  {
	for i := 0; i &lt; 50; i++ {
		intChan &lt;- i
		fmt.Println(&quot;write:&quot;, i)
	}
	close(intChan)
}

func readData(intChan chan int, exitChan chan bool) {
	for {
		v, ok := &lt;-intChan
		if !ok {
			break
		}
		time.Sleep(time.Second)
		fmt.Println(&quot;read:&quot;, v)
	}
	exitChan &lt;- true
	close(exitChan)
}

func main() {
	intChan := make(chan int, 10)
	exitChan := make(chan bool, 1)

	go writeData(intChan)
	go readData(intChan, exitChan)
	for {
		if _, ok := &lt;-exitChan; !ok{
			break
		}
	}
}
注意：如果只向管道写入数据而没有读取，就会造成堵塞而deadlock

golang/实战/go-实战-05---instance.content:
Go Instance 05
mores
使用select解决从管道取数据堵塞问题
使用select解决从管道取数据堵塞的问题，语法如下：

select语法
package main

import (
	&quot;fmt&quot;
	&quot;time&quot;
)

func main() {
	//定义一个管道，可以放10个int类型数据
	intChan := make(chan int, 10)
	for i := 0; i &lt; 10; i++ {
		intChan &lt;- i
	}
	//定义一个管道，可以放5个string类型数据
	stringChan := make(chan string, 5)
	for i := 0; i &lt; 5; i++ {
		stringChan &lt;- &quot;hello&quot; + fmt.Sprintf(&quot;%d&quot;, i)
	}
	//传统的方法遍历管道时，如果不关闭会阻塞而导致deadlock

	//实际开发中，不好确定什么时候关闭通道
	//这时可以使用select方式解决
	//label
	for {
		select {
		//管道不关闭不会deadlock，会自动到下一个case匹配
		case v := &lt;-intChan:
			fmt.Printf(&quot;从intChan读取的数据%d\n&quot;, v)
			time.Sleep(time.Second)
		case v := &lt;-stringChan:
			fmt.Printf(&quot;从stringChan读取的数据%v\n&quot;, v)
			time.Sleep(time.Second)
		default:
			fmt.Printf(&quot;取不到数据\n&quot;)
			time.Sleep(time.Second)
			return
		//break label
		}
	}
}

