Go Instance 06
defer+recover解决panic导致程序崩溃
案例1
如果我们起了一个协程，但这个协程出现了panic，但我们没有捕获这个协程，就会造成程序的崩溃，这时可以在goroutine中使用recover来捕获panic，进行处理，这样主线程不会受到影响
package main

import (
	&quot;fmt&quot;
	&quot;time&quot;
)

func sayhello() {
	for i := 0; i &lt; 10; i++ {
		fmt.Println(&quot;hello&quot;)
		time.Sleep(time.Second)
	}
}

func test() {
	//使用defer+recover
	defer func() {
		//捕获test抛出的panic
		if err := recover(); err != nil {
			fmt.Println(&quot;test 发生错误：&quot;, err)
		}
	}()

	var myMap map[int]string
	myMap[0] = &quot;golang&quot;
}

func main() {
	go sayhello()
	go test()

	for i := 0; i &lt; 10; i++ {
		fmt.Println(&quot;main() ok=&quot;, i)
		time.Sleep(time.Second)
	}
}

golang/实战/go-实战-07---instance.content:
Go Instance 07
定时器
当需要在后面一个时刻运行Go代码，或者在某段时间内重复运行。Go内置的定时器和打点器让这些很容易实现
package main

import (
	&quot;fmt&quot;
	&quot;time&quot;
)

func main() {
	//定时器表示在未来某一时刻的独立事件
	//提供定时器需要的时间，定时器将提供一个用于通知的通道
	//这里设置定时器将等待2秒
	timer1 := time.NewTimer(time.Second * 2)

	//&lt;-timer1.C 直到这个定时器的通道C明确的发送了定时器失效的值之前，一直阻塞
	&lt;-timer1.C
	fmt.Println(&quot;Timer 1 expired&quot;)

	//如果需要的仅仅是等待，可以使用Sleep
	//定时器有用的原因之一是可以在定时器失效前取消定时器
	timer2 := time.NewTimer(time.Second * 2)

	go func() {
		&lt;- timer2.C
		fmt.Println(&quot;Timer 2 expired&quot;)
	}()

	stop := timer2.Stop()
	if stop {
		fmt.Println(&quot;Timer 2 stop&quot;)
	}
}
第一个定时器将在程序开始后2秒失效，第二个在其还没失效前就被停止了
打点器
定时器是当你想要在未来某一时刻执行一次时使用，打点器是当你想要在固定的时间间隔重复执行准备的。这是一个打点器的例子，它将定时执行，直到我们将它停止
package main

import (
	&quot;fmt&quot;
	&quot;time&quot;
)

func main() {

	//打点器和定时器的机制有点相似：一个通道用来发送数据。
	// 这里我们在这个通道上使用内置的 range 来迭代值每隔500ms 发送一次的值。
	ticker := time.NewTicker(time.Millisecond * 500)

	go func() {
		for t := range ticker.C {
			fmt.Println(&quot;Tick at &quot;, t)
		}
	}()

	//打点器可以和定时器一样被停止。一旦一个打点停止了，将不能再从它的通道中接收到值。
	// 我们将在运行后 1600ms停止这个打点器。
	time.Sleep(time.Millisecond * 1000)
	ticker.Stop()
	fmt.Println(&quot;Ticker stopped&quot;)
}

golang/实战/go-实战-08---instance.content:
Go Instance 08
工作池
在这个例子中，将看到如何使用GO协程和通道实现一个工作池
package main

import (
	&quot;fmt&quot;
	&quot;time&quot;
)
//这是将要在多个并发实例中支持的任务
//这些执行者将从jobs通道接收任务，并通过results发送对应结果
//让每个任务睡1秒，模拟耗时任务
func worker(i int, jobs &lt;-chan int, results chan&lt;- int)  {
	for j := range jobs{
		fmt.Printf(&quot;worker %d processing job %d \n&quot;, i, j )
		time.Sleep(time.Second)
		results &lt;- j
	}
}

func main() {
	//使用worker工作池并收集结果，需要两个通道
	jobs := make(chan int, 100)
	results := make(chan int, 100)

	//这里启动三个worker，初始是阻塞的，因为还没有任务
	for i := 1; i &lt;= 3; i++ {
		go worker(i, jobs, results)
	}

	//发送9个任务，然后close表示这些就是所有任务了
	for i := 1; i &lt;= 9; i++ {
		jobs &lt;- i
	}
	close(jobs)

	//收集所有任务的返回值
	for i := 1; i &lt;= 9; i++ {
		&lt;-results
	}
}
执行这个程序，显示9个任务被多个worker执行。整个程序处理所有任务仅执行了3秒，因为是3个worker并行的

golang/实战/go-实战-09---instance.content:
Go Instance 09
速率限制
速率限制(英) 是一个重要的控制服务资源利用和质量的途径。Go 通过 Go 协程、通道和打点器优美的支持了速率限制。
package main

import (
	&quot;fmt&quot;
	&quot;time&quot;
)

func main() {
	//基本速率限制
	//如果想限制接收请求处理，可以将这些请求发送到一个相同通道
	requests := make(chan int, 5)

	for i := 1; i &lt;= 5; i++ {
		requests &lt;- i
	}
	close(requests)

	//这个tick通道将每200毫秒接收一个值，这个是速率限制任务中的管理器
	tick := time.Tick(time.Millisecond * 200)

	//通过在每次请求前阻塞tick通道的一个接收，限制每隔200毫秒接收一个值
	for row := range requests {
		&lt;-tick
		fmt.Println(&quot;request:&quot;, row, time.Now())
	}

	//有时候想临时进行速率限制，并且不影响整体速率控制可以使用通道缓冲来实现
	//burstyLimter通道用来进行3次临时的脉冲型速率限制
	burstyLimter := make(chan time.Time, 3)

	//将需要临时改变值传入
	for i := 0; i &lt; 3; i++ {
		burstyLimter &lt;- time.Now()
	}
	//每个200毫秒添加一个新值到通道内，直到达到3个限制
	go func() {
		for t := range time.Tick(time.Millisecond * 200) {
			burstyLimter &lt;- t
		}
	}()

	//现在模拟5个接入请求
	//刚开始3个受临时的脉冲影响
	burstyRequests := make(chan int, 5)

	for i := 0; i &lt; 5; i++ {
		burstyRequests &lt;- i
	}
	close(burstyRequests)

	for row := range burstyRequests {
		&lt;- burstyLimter
		fmt.Println(&quot;request2: &quot;, row, time.Now())
	}
}
运行程序，将看到第一批请求意料之中的大约每 200ms 处理一次。第二批请求，我们直接连续处理了 3 次，这是由于这个“脉冲”速率控制，然后大约每 200ms 处理其余的 2 个。

golang/实战/go-实战-10---instance.content:
Go 实战 10 - Instance
原子计数器
Go中最主要的状态管理方法是通过通道之间的通信完成的。在工作池的例子中有遇到，但是还是有一些其他方式来管理状态。如何使用sync/atomic包在多个Go协程中进行原子计数
package main

import (
	&quot;fmt&quot;
	&quot;runtime&quot;
	&quot;sync/atomic&quot;
	&quot;time&quot;
)
//原子计数器
func main() {
	//使用一个无符号整型(永远是正整数)来代表这个计数器
	var ops uint64 = 0
	//为了模拟并发更新，启动50个协程，对计数器每个1毫秒进行一次加一操作
	for i := 0; i &lt; 50; i++ {
		go func() {
			for {
				//使用AddUint64来让计数器自动增加，使用&amp;语法来抛出ops内存地址
				atomic.AddUint64(&amp;ops, 1)
				//允许其他Go协程执行
				runtime.Gosched()
			}
		}()
	}

	//等待1秒,让Go协程有时间运行
	time.Sleep(time.Second)
	//在计数器还在被其他Go协程更新时,安全的使用
	//通过LoadUint将当前值拷贝到opsfinal
	//LoadUint64 需要的是内存地址
	opsfinal := atomic.LoadUint64(&amp;ops)
	fmt.Println(opsfinal)
}
互斥锁
相较于简单的原子计数器，对于更复杂的情况，可以使用一个互斥锁在Go协程里安全的访问数据
package main

import (
	&quot;fmt&quot;
	&quot;math/rand&quot;
	&quot;runtime&quot;
	&quot;sync&quot;
	&quot;sync/atomic&quot;
	&quot;time&quot;
)

func main() {
	//在这个例子中state是一个map
	var state = make(map[int]int)
	//这里的mutex将同步对mutex的访问
	var mutex = &amp;sync.Mutex{}
	//为了比较基于互斥锁的处理方式和其他方式，ops将记录对state的操作次数
	var ops int64 = 0
	//运行100Go协程同时读取state
	for i := 0; i &lt; 100; i++ {
		go func() {
			total := 0
			for {
				//每次循环读取，使用一个键进行访问
				//Lock()这个mutex来确保对state的独占访问，读取选定键的值
				//Unlock()这个state并使ops+1
				key := rand.Intn(5)
				//fmt.Println(&quot;key:&quot;, key)
				mutex.Lock()
				total += state[key]
				mutex.Unlock()
				atomic.AddInt64(&amp;ops, 1)
				//为了确保这个Go协程不会在调度中饿死
				//每次操作后明确使用runtime.Gosched()进行释放
				//这个释放一般是自动处理的，例如每个通道操作后或者time.Sleep的阻塞调用后相似
				//但在这个例子中需要手动处理
				runtime.Gosched()
			}
		}()
	}

	//运行10个Go协程来模拟写操作，使用和读取相同模式
	for i := 0; i &lt; 10; i++ {
		go func() {
			for {
				key := rand.Intn(5)
				value := rand.Intn(100)
				mutex.Lock()
				state[key] = value
				mutex.Unlock()
				atomic.AddInt64(&amp;ops, 1)
				runtime.Gosched()
			}
		}()
	}
	//让这10个Go协程对state和mutex的操作运行1秒
	time.Sleep(time.Second)
	//获取并输出最终操作数
	opsFinal := atomic.LoadInt64(&amp;ops)
	fmt.Println(&quot;ops:&quot;, opsFinal)
	//对state使用一个最终锁，显示是如何结束的
	mutex.Lock()
	fmt.Println(state)
	mutex.Unlock()
}

