Go 实战 23 - Instance
信号
有时候我们希望Go能智能的处理Unix信号。例如，希望当服务器接收到一个SIGTERM信号时能自动关机，或者一个命令号工具在接收到一个SIGINT信号时停止处理输入信息。
package main

import (
	&quot;fmt&quot;
	&quot;os&quot;
	&quot;os/signal&quot;
	&quot;syscall&quot;
)

func main() {
	sigs := make(chan os.Signal, 1)
	done := make(chan bool, 1)

	//signal.Notify注册这个给定的通道用于接收特定的信号
	signal.Notify(sigs, syscall.SIGINT, syscall.SIGTERM)

	//开启一个Go协程执行阻塞信号接收的操作
	//当sign接收到一个值,将其打印,然后通知程序可以退出了
	go func() {
		sig := &lt;-sigs
		fmt.Println()
		fmt.Println(sig)
		done &lt;- true
	}()

	//程序在这等待,直到得到了期待的信号,然后退出
	fmt.Println(&quot;awaiting signal&quot;)
	&lt;- done
	fmt.Println(&quot;exiting&quot;)
}
退出
使用os.Exit来立即进行带给定状态的退出
package main

import (
	&quot;fmt&quot;
	&quot;os&quot;
)

func main() {
	//当使用os.Exit时defer将不会执行
	defer fmt.Println(&quot;!&quot;)

	//退出并且退出状态为3
	os.Exit(3)
}

golang/并发/go-并发-02---channel使用.content:
Go 并发 02 — channel使用
理论基础：CSP
Go 的并发模型基于 CSP（Communicating Sequential Processes）：

Don’t communicate by sharing memory; share memory by communicating.
— 不要通过共享内存来通信，而要通过通信来共享内存。

channel 类型

























类型声明说明双向chan T可发送和接收只发送chan&lt;- T只能发送只接收&lt;-chan T只能接收
ch := make(chan int)           // 双向
var sendOnly chan&lt;- int = ch   // 只发送
var recvOnly &lt;-chan int = ch   // 只接收

单向 channel 通常用在函数参数中，表达意图并限制滥用。

创建 channel
// 无缓冲 channel（同步）
ch := make(chan int)

// 有缓冲 channel（异步）
ch := make(chan int, 10)

// nil channel
var ch chan int  // nil，不能收发
无缓冲 channel
ch := make(chan int)

go func() {
    ch &lt;- 42      // 阻塞直到 main goroutine 接收
}()

val := &lt;-ch      // 接收，阻塞直到 goroutine 发送
fmt.Println(val) // 42

无缓冲 channel 保证发送完成发生在接收之前（同步语义）。

有缓冲 channel
ch := make(chan int, 3)

ch &lt;- 1           // 不阻塞
ch &lt;- 2           // 不阻塞
ch &lt;- 3           // 不阻塞
// ch &lt;- 4        // 阻塞：缓冲区满了

fmt.Println(&lt;-ch) // 1
fmt.Println(&lt;-ch) // 2
fmt.Println(&lt;-ch) // 3
// fmt.Println(&lt;-ch) // 阻塞：缓冲区空了
len 与 cap
ch := make(chan int, 10)
ch &lt;- 1
ch &lt;- 2

fmt.Println(len(ch)) // 2（当前元素数）
fmt.Println(cap(ch)) // 10（缓冲区容量）
关闭 channel
ch := make(chan int, 3)
ch &lt;- 1
ch &lt;- 2
close(ch)           // 关闭后不能再发送

// 方式1：ok 模式
for {
    val, ok := &lt;-ch
    if !ok {
        break      // channel 已关闭
    }
    fmt.Println(val)
}

// 方式2：range 自动检测关闭
for val := range ch {
    fmt.Println(val)
}
关闭原则

⚠️ 谁发送谁关闭，接收方不要关闭 channel。

// ✅ 正确：发送方关闭
go func() {
    for _, v := range data {
        ch &lt;- v
    }
    close(ch)       // 发送者关闭
}()

// ❌ 错误：接收方关闭（可能导致发送方 panic）
go func() {
    close(ch)       // 发送方还在往 ch 里发数据
}()
nil channel
var ch chan int   // nil

// ch &lt;- 1        // ❌ 永远阻塞
// &lt;-ch           // ❌ 永远阻塞
// close(ch)      // ❌ panic: close of nil channel

// 应用：在 select 中动态开关 channel
var ch chan int
select {
case ch &lt;- 1:     // 永远不会执行（nil channel 永远阻塞）
}
channel 常见用法
作为信号量
// 通知 goroutine 结束
done := make(chan struct{})
go func() {
    // do work
    close(done)   // 通知完成
}()
&lt;-done            // 等待完成
限制并发数
sem := make(chan struct{}, 10)  // 最大 10 个并发

for _, task := range tasks {
    sem &lt;- struct{}{}            // 获取令牌
    go func(t Task) {
        defer func() { &lt;-sem }() // 释放令牌
        process(t)
    }(task)
}
超时控制
ch := make(chan int, 1)
go func() {
    time.Sleep(2 * time.Second)
    ch &lt;- result
}()

select {
case val := &lt;-ch:
    fmt.Println(&quot;result:&quot;, val)
case &lt;-time.After(1 * time.Second):
    fmt.Println(&quot;timeout&quot;)
}
