golang/并发/go-并发-03---select多路复用.content:
Go 并发 03 — select多路复用
select 基础
select 让一个 goroutine 同时等待多个 channel 操作：
select {
case &lt;-ch1:
    fmt.Println(&quot;received from ch1&quot;)
case ch2 &lt;- 1:
    fmt.Println(&quot;sent to ch2&quot;)
}

























特性说明同时就绪随机选择一个执行无就绪阻塞直到某个 case 就绪nil channel永远阻塞（相当于禁用这个 case）空 select永久阻塞（select {}）
空 select
// 永久阻塞 main goroutine
// 通常用于让程序持续运行（如服务端）
select {}
default — 非阻塞操作
select {
case val := &lt;-ch:
    fmt.Println(&quot;received:&quot;, val)
default:
    fmt.Println(&quot;no data available&quot;)  // 非阻塞：没有就绪立即执行 default
}
非阻塞发送
select {
case ch &lt;- val:
    fmt.Println(&quot;sent&quot;)
default:
    fmt.Println(&quot;channel full, dropping value&quot;)  // buffer 满时不阻塞
}
超时控制
select {
case result := &lt;-ch:
    fmt.Println(&quot;result:&quot;, result)
case &lt;-time.After(3 * time.Second):
    fmt.Println(&quot;timeout after 3s&quot;)
}

注意：time.After 每次调用都会创建新 timer，如果在循环中使用会导致内存泄漏。循环中应该用 time.NewTimer。

循环中的 select — 多路监听
ch1 := make(chan int)
ch2 := make(chan int)

go producer1(ch1)
go producer2(ch2)

for i := 0; i &lt; 10; i++ {
    select {
    case v := &lt;-ch1:
        fmt.Println(&quot;ch1:&quot;, v)
    case v := &lt;-ch2:
        fmt.Println(&quot;ch2:&quot;, v)
    }
}
优先级实现
select 本身不支持优先级，但可以用嵌套 select + 循环实现：
// 优先处理 ch1，ch1 没有数据才处理 ch2
for {
    select {
    case job1 := &lt;-ch1:
        fmt.Println(&quot;high priority:&quot;, job1)
    default:
        select {
        case job1 := &lt;-ch1:
            fmt.Println(&quot;high priority:&quot;, job1)
        case job2 := &lt;-ch2:
            fmt.Println(&quot;normal:&quot;, job2)
        }
    }
}
K8s 中的优先级 select 实战
// kubernetes/pkg/controller/nodelifecycle/scheduler/taint_manager.go
func (tc *NoExecuteTaintManager) worker(worker int, done func(), stopCh &lt;-chan struct{}) {
    defer done()
    for {
        select {
        case &lt;-stopCh:
            return
        case nodeUpdate := &lt;-tc.nodeUpdateChannels[worker]:
            tc.handleNodeUpdate(nodeUpdate)
            tc.nodeUpdateQueue.Done(nodeUpdate)
        case podUpdate := &lt;-tc.podUpdateChannels[worker]:
            // 发现 Pod 需要更新时，先清空 Node 队列
        priority:
            for {
                select {
                case nodeUpdate := &lt;-tc.nodeUpdateChannels[worker]:
                    tc.handleNodeUpdate(nodeUpdate)
                    tc.nodeUpdateQueue.Done(nodeUpdate)
                default:
                    break priority
                }
            }
            tc.handlePodUpdate(podUpdate)
            tc.podUpdateQueue.Done(podUpdate)
        }
    }
}
select + for + timer — 循环中的超时
// ✅ 推荐：复用 Timer
ticker := time.NewTicker(5 * time.Second)
defer ticker.Stop()

for {
    select {
    case &lt;-ticker.C:
        fmt.Println(&quot;tick every 5s&quot;)
    case &lt;-ch:
        fmt.Println(&quot;processed job&quot;)
    case &lt;-ctx.Done():
        fmt.Println(&quot;stopped&quot;)
        return
    }
}
select + done channel — 优雅退出
func worker(stop &lt;-chan struct{}) {
    for {
        select {
        case job := &lt;-jobCh:
            process(job)
        case &lt;-stop:
            fmt.Println(&quot;worker shutting down&quot;)
            return
        }
    }
}
