golang/进阶/go-进阶-01---context.content:
Go 进阶 01 - Context
Go标准库Context
在Go http包的server中，每一个请求在都有一个对应的goroutine去处理。请求处理函数通常会启动额外的goroutine用来访问后端服务，比如数据库和RPC服务。用来处理一个请求的goroutine通常需要访问一些与请求特定的数据，比如终端用户的身份认证信息，验证相关的token，请求的截止时间。当一个请求被取消或超时时，所有用来处理该请求的goroutine都应该迅速退出，然后系统才能释放这些goroutine占用的资源。
为什么需要Context
基本示例
package main

import (
	&quot;fmt&quot;
	&quot;sync&quot;
	&quot;time&quot;
)

var wg sync.WaitGroup

// 初始的例子

func work() {
	for {
		fmt.Println(&quot;worker&quot;)
		time.Sleep(time.Second)
    }
    // 如何接收外部命令实现退出
	wg.Done()
}

func main() {
	wg.Add(1)
	go work()
    // 如何优雅的实现结束子goroutine
	wg.Wait()
	fmt.Println(&quot;over&quot;)
}
全局变量方式
package main

import (
	&quot;fmt&quot;
	&quot;sync&quot;
	&quot;time&quot;
)
//全局变量方式存在的问题：
//1.使用全局变量在跨包调用时不容易统一
//2.如果在worker中再启动goroutine，就不太好控制了

var wg2 sync.WaitGroup
var exit bool

func work2() {
	for {
		fmt.Println(&quot;work&quot;)
		time.Sleep(time.Second)
		if exit {
			break
		}
	}
	wg2.Done()
}

func main() {
	wg2.Add(1)
	go work2()
	//sleep3秒避免程序过早退出
	time.Sleep(time.Second * 3)
	//修改全局变量实现子goroutine的退出
	exit = true
	wg2.Wait()
	fmt.Println(&quot;over&quot;)
}
通道方式
package main

import (
	&quot;fmt&quot;
	&quot;sync&quot;
	&quot;time&quot;
)

var wg sync.WaitGroup

//管道方式存在的问题
//1.使用全局变量在跨包调用时不容易实现规范和统一，需要维护一个共同的channel

func work3(exitChan chan struct{}) {
	LOOP:
		for {
			fmt.Println(&quot;work&quot;)
			time.Sleep(time.Second)
			select {
			//等待接收上级通知
			case &lt;- exitChan:
				break LOOP
			default:
			}
		}
		 wg.Done()
}

func main() {
	wg.Add(1)
	exitChan := make(chan struct{})
	go work3(exitChan)
	//sleep3秒避免程序过早退出
	time.Sleep(time.Second * 3)
	//给子goroutine发送退出信号
	exitChan &lt;- struct {}{}
	close(exitChan)
	wg.Wait()
	fmt.Println(&quot;over&quot;)
}
官方版的方案
gopackage main

import (
	&quot;context&quot;
	&quot;fmt&quot;
	&quot;sync&quot;
	&quot;time&quot;
)

var wg4 sync.WaitGroup

func work4(ctx context.Context) {
	LOOP:
		for {
			fmt.Println(&quot;work4&quot;)
			time.Sleep(time.Second)
			select {
			case &lt;- ctx.Done():
				break LOOP
			default:
			}
		}
		wg4.Done()
}

func main() {
	wg4.Add(1)
	ctx, cancel := context.WithCancel(context.Background())
	go work4(ctx)
	time.Sleep(time.Second*3)
	cancel()
	wg4.Wait()
	fmt.Println(&quot;over&quot;)
}
当子goroutine又开启另一个goroutine时，只需将ctx传入即可
package main

import (
	&quot;context&quot;
	&quot;fmt&quot;
	&quot;sync&quot;
	&quot;time&quot;
)

var wg5 sync.WaitGroup

func work5(ctx context.Context) {
	go work5_2(ctx)
	LOOP:
		for {
			fmt.Println(&quot;work5&quot;)
			time.Sleep(time.Second)
			select {
			//等待上级通知
			case &lt;-ctx.Done():
				break LOOP
			default:
			}
		}
		wg5.Done()
}

func work5_2(ctx context.Context) {
	LOOP:
		for {
			fmt.Println(&quot;work5_2&quot;)
			time.Sleep(time.Second)
			select {
			//等待上级通知
			case &lt;-ctx.Done():
				break LOOP
			default:
			}
		}
}

func main() {
	wg5.Add(1)
	ctx, cancel := context.WithCancel(context.Background())
	go work5(ctx)
	time.Sleep(time.Second * 3)
	//通知子goroutine结束
	cancel()
	wg5.Wait()
	fmt.Println(&quot;over&quot;)
}
Context初识
Go1.7加入了一个新的标准库context，它定义了Context类型，专门用来简化对于处理单个请求的多个goroutine之间与请求域的数据，取消信号、截止时间等相关操作，这些操作可能涉及多个API调用。
对服务器传入的请求应该创建上下文，而对服务器的传出调用应该接受上下文，它们之间的函数调用链必须传递上下文，或者可以使用WithCancel、WithDeadline、WithTimeout或WithValue创建派生的上下文。当一个上下文被取消时，它派生的所有上下文也被取消。
Context接口
context.Context是一个接口，该接口定义了四个需要实现的方法。具体接口如下：
type Context interface {
	Deadline() (deadline time.Time, ok bool)
	Done() &lt;-chan struct{}
	Err() error
	Value(key interface{}) interface{}
}
其中：


Deadline方法返回需要返回当前Context被取消的时间，也就是完成工作的时间


Done方法返回需要一个Channel，这个Channel会在当前工作完成或者上下文被取消后关闭，多次调用Done方法会返回同一Channel


Err方法会返回当前Context结束的原因，它只会在Done返回的Channel被关闭时才会返回非空的值


如果当前的Context被取消就会返回Canceled错误


如果当前的Context超时就会返回DeadlineExceeded错误


Value方法会从Context中返回键对应的值，对于同一个上下文来说，多次调用Value并传入相同的Key会返回相同的结果，该方法仅用于传递跨API和进程间跟请求域的数据


Background()和TODO()
Go内置两个函数：Background()和TODO()，这两个函数分别返回一个实现了Context接口的background和todo。我们代码中最开始都是以这两个内置的上下文对象作为最顶层的parent context，衍生出更多的子上下文对象。
Background()主要作用于main函数，初始化以及测试代码中，作为Context这个树结构最顶层的Context，也就是根Context。
TODO()，它目前还不知道具体的使用场景，如果我们不知道该使用什么Context的使用可以使用这个。
backgroud和todo本质上都是emptyCtx结构类型，是一个不可取消，没有设置截止时间，没有携带任何值的Context。
With系列函数
此外，context包中还定义了四个With系列函数。
WithCancel
WithCancel的函数如下：
func WithCancel(parent Context) (ctx Context, cancel CancelFunc)
WithCancel返回带有新Done通道的父节点的副本。当调用返回的cancel函数或当关闭父上下文的Done通道时，将关闭返回上下文的Done通道，无论发生什么情况。
取消此上下文将释放与其关联的资源，因此代码应该在此上下文中运行的操作完成后立即调用cancel。
package main

import (
	&quot;context&quot;
	&quot;fmt&quot;
)

func gen(ctx context.Context) &lt;- chan int {
	dst := make(chan int)
	n := 1
	go func() {
		for {
			select {
			case &lt;-ctx.Done():
				//return结束该goroutine，防止泄露
				return
			case dst &lt;- n:
				n++
			}
		}
	}()
	return dst
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	//当取完需要的整数后调用cancel
	defer cancel()
	for r := range gen(ctx) {
		fmt.Println(r)
		if r == 5 {
			break
		}
	}
}
上面的示例代码中，gen函数在单独的goroutine中生成整数并将它们发送到返回的通道。gen的调用者在使用生成的整数之后需要取消上下文，以免gen启动的内部goroutine发生泄漏。
WithDeadline
WithDeadline的函数接口如下
func WithDeadline(parent Context, d time.Time) (Context, CancelFunc)
返回父上下文的副本，并将d调整不迟于deadline。如果父上下文的d已经早于deadline，则WithDeadline(parent, d)在语义上等同于父上下文。当截止日过期时，当调用返回的cancel函数时，或者当父上下文的Done通道关闭时，返回上下文的Done通道将被关闭，以最先发生的情况为准。
取消上下文将释放与其关联的资源，因此代码应该在此上下文中运行的操作完成后立即调用cancel。
package main

import (
	&quot;context&quot;
	&quot;fmt&quot;
	&quot;time&quot;
)

func main() {
	d := time.Now().Add(time.Millisecond * 500)
	ctx, cancel := context.WithDeadline(context.Background(), d)
	defer cancel()

	select {
	case &lt;-time.After(time.Second):
		fmt.Println(&quot;overslept&quot;)
	case &lt;-ctx.Done():
		fmt.Println(ctx.Err())
	}
}
上面的代码中分，定义了一个500毫秒之后过期的deadline，然后我们调用context.WithDeadline(context.Backgroud(), d)得到一个上下文(ctx)和一个取消函数(cancel)，然后使用一个select让主程序陷入等待：等待1秒后打印overslept退出或者等待ctx过期后退出。因为ctx500毫秒后就过期了，所以ctx.Done()会先接收到值，上面代码会打印ctx.Err()取消原因。
WithTimeout
WithTimeout的函数接口如下
func WithTimeout(parent Context, timeout time.Duration) (Context, CancelFunc)
WithTimeout返回WithDeadline(parent, time.Now().Add(timeout))
取消此上下文将释放与其相关的资源，因此代码应该在上下文中运行的操作完成后立即调用cancel，通常用于数据库或者网络连接的超时控制。具体示例如下：
package main

import (
	&quot;context&quot;
	&quot;fmt&quot;
	&quot;sync&quot;
	&quot;time&quot;
)

var wg8 sync.WaitGroup

func work8(ctx context.Context) {
	LOOP:
		for {
			fmt.Println(&quot;db connect...&quot;)
			//假设正常连接数据库需要10毫秒
			time.Sleep(time.Millisecond * 10)
			select {
			//50毫秒后自动调用
			case &lt;-ctx.Done():
				break LOOP
			default:
			}
		}
		fmt.Println(&quot;work done&quot;)
		wg8.Done()
}

func main() {
	//设置一个50毫秒的超时
	ctx, cancel := context.WithTimeout(context.Background(), time.Millisecond*50)

	wg8.Add(1)
	go work8(ctx)
	time.Sleep(time.Second * 5)
	//通知子goroutine结束
	cancel()
	wg8.Wait()
	fmt.Println(&quot;over&quot;)
}
WithValue
WithValue 函数能够将请求作用域的数据与Context对象建立联系。函数接口如下：
func WithValue(parent Context, key, val interface{}) Context
WithValue返回父节点的副本，其中与key关联的值是val。
仅对API和进程传递请求域的数据使用上下文值，而不是使用它来传递可选参数给函数。
所提供的键必须是可比较的，并且不应该是string类型或任何其他内置类型，以避免使用上下文在包之间发生冲突。WithValue的用户应该为键定义自己的类型。为了避免在分配给interface{}时进行分配，上下文通常具有具体类型struct{}。或者，导出的上下文关键变量的静态类型应该是指针或接口。
package main

import (
	&quot;context&quot;
	&quot;fmt&quot;
	&quot;sync&quot;
	&quot;time&quot;
)

var wg9 sync.WaitGroup
type TraceCode string

func work9(ctx context.Context) {
	key := TraceCode(&quot;Trace_Code&quot;)
	//在子goroutine中获取TraceCode
	traceCode, ok := ctx.Value(key).(string)
	if !ok {
		fmt.Println(&quot;invalid trace code&quot;)
	}
	LOOP:
		for {
			fmt.Printf(&quot;worker, trace code: %s\n&quot;, traceCode)
			//假设正常连接数据库需要10毫秒
			time.Sleep(time.Millisecond * 10)
			select {
			//50毫秒后自动调用
			case &lt;-ctx.Done():
				break LOOP
			default:
			}
		}
		fmt.Println(&quot;work done&quot;)
	wg9.Done()
}

func main() {
	//设置一个50毫秒的超时
	ctx, cancel := context.WithTimeout(context.Background(), time.Millisecond*50)
	//在系统入口设置trace code传递给后续启动的子goroutine实现日志数据聚合
	ctx = context.WithValue(ctx, TraceCode(&quot;Trace_Code&quot;), &quot;12345&quot;)
	wg9.Add(1)
	go work9(ctx)
	time.Sleep(time.Second * 5)
	//通知子goroutine结束
	cancel()
	wg9.Wait()
	fmt.Println(&quot;over&quot;)
}
使用Context的注意事项

推荐以参数的方式显示传递Context。
以Context作为参数的函数方法，应该把Context作为第一参数。
给一个函数方法传递Context的时候，不要传递nil，如果不知道传递什么，就使用context.TODO()
Context的Value相关方法应该传递请求域的必要数据，不应该用于传递可选参数。
Context是线程安全的，可以放心的在多个goroutine中传递。

golang/进阶/go-进阶-03---单元测试.content:
Go 进阶 03 - 单元测试
Go语言测试
go test工具
Go语言中的测试依赖go test命令。编写测试代码和编写普通的Go代码过程是类似的，并不需要学习新的语法、规则和工具。
go test命令是一个按照一定约定和组织的测试代码的驱动程序。在包目录内，所有以_test.go为后缀名的源代码文件都是go test测试的一部分，不会被go build编译到最终可执行文件中。
在*_test.go文件中有三种类型的函数，单元测试函数、基准测试函数和示例函数。
| 类型 | 格式 | 作用 |
| 测试函数 | 函数名前缀为Test | 测试程序的一些逻辑行为是否正确 |
| 基准函数 | 函数名前缀为Benchmark | 测试函数的性能 |
| 示例函数 | 函数名前缀为Example | 为文档提供示例文档 |
go test命令会遍历所有的*_test.go文件中符合上述命名规则的函数，然后生成一个临时的main包用于调用相应的测试函数，然后构建并运行、报告测试结果，最后清理测试中产生的临时文件。
单元测试函数
格式
每个函数必须导入testing包，测试函数的基本格式(签名)如下：
func TestName(t *testing.T) {
    // ...
}
测试函数的名字必须以Test开头，可选的后缀名必须以大写字母开头，举几个例子：
func TestAdd(t *testing.T) {}
func TestSum(t *testing.T) {}
func TestLog(t *testing.T) {}
其中参数t用于报告测试失败和附加的日志信息。testing.T拥有的方法如下：
func (c *T) Cleanup(func())
func (c *T) Error(args ...interface{})
func (c *T) Errorf(format string, args ...interface{})
func (c *T) Fail()
func (c *T) FailNow()
...
单元测试示例
就像细胞是构成我们身体的基本单位，一个软件程序也是由很多单元组件构成的。单元组件可以是函数、结构体、方法和最终用户可能依赖的任意东西。总之我们需要确保这些 组件是能够正常运行的。单元测试是一些利用各种方法测试单元组件的程序，它会将结果与预期输出进行比较。
接下来，我们在base_demo包中定义了一个Split函数，具体实现如下：
package base_demo

import &quot;strings&quot;

// Split 把字符串s按照指定的分隔符sep进行分割返回字符串切片
func Split(s, sep string) (result []string) {
    i := strings.Index(s, sep)

    for i &gt; -1 {
        result = append(result, s[:i])
        s = s[i+1:]
        i = strings.Index(s, sep)
    }

    result = append(result, s)
    return
}
在当前目录下我们创建一个split_test.go的测试文件，并定义一个测试函数如下：
package split

import(
    &quot;reflect&quot;
    &quot;testing&quot;
)

// 函数名必须以Test开头，必须接收一个*testing.T类型参数
func TestSplit(t *testing.T) {
    // 程序输出结果
    got := Split(&quot;a🅱️c&quot;, &quot;:&quot;)
    // 期望的结果
    want := []string{&quot;a&quot;, &quot;b&quot;, &quot;c&quot;}
    // 因为slice不能比较直接，借助反射包中的方法比较
    if !reflect.DeepEqual(want, got) {
        // 测试失败输出错误提示
        t.Errorf(&quot;expected: %v, got: %v&quot;, want, got)
    }
}
在当前路径下执行go test命令，可以看见输出结果
go test -v
一个测试用例有点单薄，我们再编写一个测试使用多个字符切割字符串的例子，在split_test.go中添加如下测试函数：
func TestSplitWithComplexSep(t *testing.T) {
    got := Split(&quot;abcd&quot;, &quot;bc&quot;)
    want := []string{&quot;a&quot;, &quot;d&quot;}
    if !reflect.DeepEqual(want, got) {
        t.Errorf(&quot;expected: %v, got: %v&quot;, want, got)
    }
}
现在我们有多个测试用例了，为了能更好的在输出结果中看见每一个测试用例的执行情况，我们可以为go test命令添加-v参数，让它输出完整的测试结果
从输出结果我们能清楚的看到TestSplitWithComplexSep这个测试用例没有测试通过。
go test -run
单元测试的结果表明split这个函数的实现并不可靠，没有考虑到传入的sep参数是多个字符的情况，下面修复这个bug：
package base_demo

import &quot;strings&quot;

// Split 把字符串s按照指定的分隔符sep进行分割返回字符串切片
func Split(s, sep string) (result []string) {
    i := strings.Index(s, sep)

    for i &gt; -1 {
        result = append(result, s[:i])
        // 这里使用len(sep)获取sep的长度
        s = s[i+len(sep):]
        i = strings.Index(s, sep)
    }

    result = append(result, s)
    return
}
在执行go test命令的时候可以添加-run参数，它对应的是一个正则表达式，只有函数名匹配上的测试函数才会被go test命令执行
例如通过给go test添加-run=Sep参数来告诉它本次测试只运行TestSplitWithComplexSep这个测试用例
回归测试
修改代码后仅仅执行那些失败的测试用例或新引入的测试用例是错误且危险的，正确的做法应该是完整运行所有的测试用例，保证不会因为修改代码而引入新的问题
通过这个示例我们可以看到，有了单元测试就能够在代码改动后快速进行回归测试，极大地提高开发效率和保证代码的质量。
跳过某些测试用例
为了节省时间支持在单元测试时跳过某些耗时的测试用例
func TestTimeConsuming(t *testing.T) {
    if testing.Short() {
        t.Skip(&quot;Short 模式下会跳过该测试用例&quot;)
    }
}
当执行go test short时就不会执行上面的TestTimeConsuming测试用例
子测试
在上面的示例中我们为每一个测试数据编写一个测试函数，而通常单元测试中需要多组测试数据保证测试的效果。Go1.7+中新增了子测试，支持在测试函数中使用t.Run执行一组测试用例，这样就不需要为不用的测试数据定义多个测试函数了
func TestXXX(t *testing.T) {
    t.Run(&quot;case1&quot;, func(t *testing.T){})
    t.Run(&quot;case2&quot;, func(t *testing.T){})
    t.Run(&quot;case3&quot;, func(t *testing.T){})
}
表格驱动测试
介绍
表格驱动测试不是工具、包或其他任何东西，它只是编写更清晰测试的一种方式和视角
编写好的测试并非易事，但在许多情况下，表格驱动测试可以涵盖很多方面：表格里的每一个条目都是一个完整的测试用例，包含输入和预期结果，有时还包含测试名称等附加信息，以使测试输出易于阅读。
使用表格驱动测试能够很方便的维护多个测试用例，避免在编写单元测试时频繁的复制粘贴。
表格驱动测试的步骤通常是定义一个测试用例表格，然后遍历表格，并使用t.Run对每一个条目执行必要的测试。
示例
官方标准库中有很多表格驱动测试的示例，例如fmt包中就有如下测试代码：
var flagtests = []struct {
	in  string
	out string
}{
	{&quot;%a&quot;, &quot;[%a]&quot;},
	{&quot;%-a&quot;, &quot;[%-a]&quot;},
	{&quot;%+a&quot;, &quot;[%+a]&quot;},
	{&quot;%#a&quot;, &quot;[%#a]&quot;},
	{&quot;% a&quot;, &quot;[% a]&quot;},
	{&quot;%0a&quot;, &quot;[%0a]&quot;},
	{&quot;%1.2a&quot;, &quot;[%1.2a]&quot;},
	{&quot;%-1.2a&quot;, &quot;[%-1.2a]&quot;},
	{&quot;%+1.2a&quot;, &quot;[%+1.2a]&quot;},
	{&quot;%-+1.2a&quot;, &quot;[%+-1.2a]&quot;},
	{&quot;%-+1.2abc&quot;, &quot;[%+-1.2a]bc&quot;},
	{&quot;%-1.2abc&quot;, &quot;[%-1.2a]bc&quot;},
}
func TestFlagParser(t *testing.T) {
	var flagprinter flagPrinter
	for _, tt := range flagtests {
		t.Run(tt.in, func(t *testing.T) {
			s := Sprintf(tt.in, &amp;flagprinter)
			if s != tt.out {
				t.Errorf(&quot;got %q, want %q&quot;, s, tt.out)
			}
		})
	}
}
通常表格是匿名结构体的切片，可以定义结构体或使用已经存在的结构进行结构体数组声明。name属性用来描述特定的测试用例。
接下来让我们试着自己编写表格驱动测试：
func TestSplitAll(t *testing.T) {
	// 定义测试表格
	// 这里使用匿名结构体定义了若干个测试用例
	// 并且为每个测试用例设置了一个名称
	tests := []struct {
		name  string
		input string
		sep   string
		want  []string
	}{
		{&quot;base case&quot;, &quot;a🅱️c&quot;, &quot;:&quot;, []string{&quot;a&quot;, &quot;b&quot;, &quot;c&quot;}},
		{&quot;wrong sep&quot;, &quot;a🅱️c&quot;, &quot;,&quot;, []string{&quot;a🅱️c&quot;}},
		{&quot;more sep&quot;, &quot;abcd&quot;, &quot;bc&quot;, []string{&quot;a&quot;, &quot;d&quot;}},
		{&quot;leading sep&quot;, &quot;沙河有沙又有河&quot;, &quot;沙&quot;, []string{&quot;&quot;, &quot;河有&quot;, &quot;又有河&quot;}},
	}
	// 遍历测试用例
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) { // 使用t.Run()执行子测试
			got := Split(tt.input, tt.sep)
			if !reflect.DeepEqual(got, tt.want) {
				t.Errorf(&quot;expected:%#v, got:%#v&quot;, tt.want, got)
			}
		})
	}
}
在终端执行go test -v， 会得到测试输出结果
并行测试
表格驱动测试中通常会定义比较多的测试用例，而Go语言又天生支持并发，所以很容易就发挥自身并发优势将表格驱动测试并行化。想要在单元测试过程中使用并行测试，可以像下面的代码示例中那样通过添加t.Parallel()来实现
func TestSplitAll(t *testing.T) {
	t.Parallel()  // 将 TLog 标记为能够与其他测试并行运行
	// 定义测试表格
	// 这里使用匿名结构体定义了若干个测试用例
	// 并且为每个测试用例设置了一个名称
	tests := []struct {
		name  string
		input string
		sep   string
		want  []string
	}{
		{&quot;base case&quot;, &quot;a🅱️c&quot;, &quot;:&quot;, []string{&quot;a&quot;, &quot;b&quot;, &quot;c&quot;}},
		{&quot;wrong sep&quot;, &quot;a🅱️c&quot;, &quot;,&quot;, []string{&quot;a🅱️c&quot;}},
		{&quot;more sep&quot;, &quot;abcd&quot;, &quot;bc&quot;, []string{&quot;a&quot;, &quot;d&quot;}},
		{&quot;leading sep&quot;, &quot;沙河有沙又有河&quot;, &quot;沙&quot;, []string{&quot;&quot;, &quot;河有&quot;, &quot;又有河&quot;}},
	}
	// 遍历测试用例
	for _, tt := range tests {
		tt := tt  // 注意这里重新声明tt变量（避免多个goroutine中使用了相同的变量）
		t.Run(tt.name, func(t *testing.T) { // 使用t.Run()执行子测试
			t.Parallel()  // 将每个测试用例标记为能够彼此并行运行
			got := Split(tt.input, tt.sep)
			if !reflect.DeepEqual(got, tt.want) {
				t.Errorf(&quot;expected:%#v, got:%#v&quot;, tt.want, got)
			}
		})
	}
}
这样我们执行go test -v的时候就会看到每个测试用例并不是按照我们定义的顺序执行的，而是互相并行的。
使用工具生成测试代码
社区里有很多自动生成表格驱动测试函数的工具，比如gotests等，很多编辑器如Goland也支持快速生成测试文件。这里简单演示一下gotests的使用。
安装
go get -u github.com/cweill/gotests/...
执行
gotests -all -w split.go
上面的命令表示，为split.go文件的所有函数生成测试代码至split_test.go文件(目录下如果事先存在这个文件就不再生成了)
代码格式与我们上面的类似，只需要在TODO位置添加我们的测试逻辑就可以了
测试覆盖率
测试覆盖率是指代码被测试套件覆盖的百分比。通常我们使用的语句都是有覆盖率，也就是在测试中至少被运行一次的代码占总代码的比例。在公司内部一般会要求测试覆盖率达到80%左右。
Go提供内置功能来检查你的代码覆盖率，即使用go test -cover来查看测试覆盖率
Go还提供了一个额外的-coverprofile参数，用来将覆盖率相关的记录信息输出到一个文件。
go test -cover -coverprofil=c.out
上面的命令会将覆盖率相关的信息输出到当前文件夹下面的c.out文件中
然后我们执行go tool cover -html=c.out，使用cover工具来处理生成的记录信息，该命令会打开本地的浏览器窗口生成一个html报告
testify/assert
testify是一个社区非常流行的Go单元测试工具包，其中使用最多的就是它提供的断言工具–testify/assert或testify/require
安装
go get github.com/stretchr/testify
使用示例
我们在写单元测试的时候，通常需要使用断言来校验测试结果，但是由于Go语言官方没有提供断言，所以我们会写出很多的if...else...语句。而testify/assert为我们提供了很多常用的断言函数，并且能够输出友好，易于阅读的错误描述信息。
比如之前在TestSplit测试函数中就使用了reflect.DeepEqual来判断期待结果与实际结果是否一致。
t.Run(tt.name, func(t *testing.T) { // 使用t.Run()执行子测试
	got := Split(tt.input, tt.sep)
	if !reflect.DeepEqual(got, tt.want) {
		t.Errorf(&quot;expected:%#v, got:%#v&quot;, tt.want, got)
	}
})
使用testify/assert之后就能将上述判断过程简化如下：
t.Run(tt.name, func(t *testing.T) { // 使用t.Run()执行子测试
	got := Split(tt.input, tt.sep)
	assert.Equal(t, got, tt.want)  // 使用assert提供的断言函数
})
当我们有多个断言语句时，还可以使用assert := assert.New(t)创建一个assert对象，它拥有前面所有的断言方法，只是不需要再传入Testing.T参数了。
总结
本文介绍了Go语言单元测试的基本用法，通过为Split函数编写单元测试的真实案例，模拟了日常开发过程中的场景，一步一步详细介绍了表格驱动测试、回归测试和常用的测试工具testify/assert的使用。

golang/进阶/go-进阶-04---网络测试.content:
Go 进阶 04 - 网络测试
httptest
在Web开发场景下的单元测试，如果涉及到HTTP请求推荐大家使用Go标准库net/http/httptest进行测试，能够显著提升效率。
在这一小节，我们以常见的gin框架为例，演示如何为http server编写单元测试
假设我们的业务逻辑是搭建一个http server端，对外提供http服务。我们编写一个helloHandle函数，用来处理用户请求。
// gin.go
package httptest_demo

import (
    &quot;fmt&quot;
    &quot;net/http&quot;

    &quot;github.com/gin-gonic/gin&quot;
)

// Param 请求参数
type Param struct {
    Name    string  `json:&quot;name&quot;`
}

// helloHandle /hello请求处理函数
func helloHandler(c *gin.Context) {
    var p Param

    if err := c.ShouldBindJSON(&amp;p); err != nil {
        c.JSON(http.StatusOK, gin.H{
            &quot;msg&quot;: &quot;we need a name&quot;,
        })
        return
    }

    c.JSON(http.StatusOK, gin.H{
        &quot;msg&quot;: fmt.Sprintf(&quot;hello %s&quot;, p.Name)
    })
}

// 路由
func SetupRouter() *gin.Engine {
    router := gin.Default()
    router.POST(&quot;/hello&quot;, helloHandler)
    return router
}
现在我们需要为helloHander函数编写单元测试，这种情况下我们就可以使用httptest这个工具mock一个HTTP请求和响应记录器，让我们的server端接收并处理我们mock的HTTP请求，同时使用响应记录器来记录server端返回的响应内容。
单元测试的示例代码如下：
// gin_test.go
package httptest_demo

import (
    &quot;encoding/json&quot;
    &quot;net/http&quot;
    &quot;net/http/httptest&quot;
    &quot;strings&quot;
    &quot;testing&quot;

    &quot;github.com/stretchr/testify/assert&quot;
)

func Test_helloHandler(t *testing.T) {
    // 定义两个测试用例
    tests := []struct{
        name    string
        param   string
        expect  string
    } {
        {&quot;base case&quot;, `{&quot;name&quot;: &quot;cc&quot;}`, &quot;hello cc&quot;},
        {&quot;bad case&quot;, &quot;&quot;, &quot;we need a name&quot;},
    }

    r := SetupRouter()

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            // mock一个http请求
            req := httptest.NewRequest(
                // 请求方法
                &quot;POST&quot;,
                // 请求URL
                &quot;/hello&quot;,
                // 请求参数
                strings.NewReader(tt.Param),
            )

            // mock一个响应记录器
            w := httptest.NewRecorder()

            // 让server端处理mock请求并记录返回的响应内容
            r.ServeHttp(w, req)

            // 校验状态码是否符合预期
            assert.Equal(t, http.StatusOK, w.Code)

            // 解析并检验响应内容是否符合预期
            var resp map[string]string
            err := json.Unmarshal([]byte(w.Body.String()), &amp;resp)
            assert.Nil(t, err)
            assert.Equal(t, tt.expect, resp[&quot;msg&quot;])
        })
    }
}
通过这个示例我们就掌握了如何使用httptest在HTTP Server服务中为请求处理函数编写单元测试了。
gock
上面的示例介绍了如何在HTTP Server服务类场景下为请求处理函数编写单元测试，那么如果我们是在代码中请求外部API的场景(比如通过API调用其他服务获取返回值)又该怎么编写单元测试呢？
例如，我们有以下业务逻辑代码，依赖外部API：your-api.com/post提供的数据。
// api.go

// ReqParam API请求参数
type ReqParam struct {
    X   int `json:&quot;x&quot;`
}

// Result API返回结果
type Result struct {
    Value   int `json:&quot;value&quot;`
}

func GetResultByAPI(x, y int) int {
    p := &amp;ReqParam{X: x}
    b, _ := json.Marshal(p)

    // 调用其他服务的API
    resp, err := http.Post(
        &quot;your-api.com/post&quot;,
        &quot;application/json&quot;,
        bytes.NewBuffer(b),
    )
    if err != nil {
        return -1
    }

    body, _ := ioutil.ReadAll(resp.Body)
    var ret Result
    if err := json.Unmarshal(body, &amp;ret); err != nil {
        return -1
    }

    // 这里是对API返回的数据做一些逻辑处理
    return ret.Value + y
}
在对类似上述这类业务代码编写单元测试的时候，如果不想在测试过程中真正去发送请求或者依赖的外部接口还没开发完成时，我们可以在单元测试中对依赖的API进行mock。
安装
go get -u gopkg.in/h2non/gock.v1
使用示例
使用gock对外部API进行mock，即mock指定参数返回约定好的响应内容。下面的代码中mock了两组数据，组成了两个测试用例
// api_test.go
package gock_demo

import (
    &quot;testing&quot;

    &quot;github.com/stretchr/testify/assert&quot;
    &quot;gopkg.in/h2non/gock.v1&quot;
)

func TestGetResultByAPI(t *testing.T) {
    // 测试执行结束后刷新挂起的mock
    defer gock.Off()

    // mock请求外部api时传参x=1返回100
    gock.New(&quot;your-api.com&quot;).
        Post(&quot;/post&quot;).
        MatchType(&quot;json&quot;).
        JSON(map[string]int{&quot;x&quot;: 1}).
        Reply(200).
        JSON(map[string]int{&quot;value&quot;: 100})

    // 调用我们的业务函数
    res := GetResultByAPI(1, 1)
    // 校验返回结果是否符合预期
    assert.Equal(t, res, 101)

    // mock请求外部API时传参x=2返回200
    gock.New(&quot;your-api.com&quot;).
        Post(&quot;/post&quot;).
        MatchType(&quot;json&quot;).
        JSON(map[string]int{&quot;x&quot;: 2}).
        Reply(200).
        JSON(map[string]int{&quot;value&quot;: 200})

    // 调用我们的业务函数
    res = GetResultByAPI(2, 2)
    // 校验返回结果是否符合预期
    assert.Equal(t, res, 202)

    // 断言mock被触发
    assert.True(t, gock.IsDone())
}
测试结果和预期完全一致
总结
作为日常开发中为代码编写单元测试时如何处理外部依赖是最常见的问题，本文介绍了如何使用httptest和gock工具mock相关依赖。

golang/进阶/go-进阶-05---mysql和redis测试.content:
Go 进阶 05 - MySQL和Redis测试
go-sqlmock
sqlmock是一个实现sql/driver的mock库。它不需要建立真正的数据库连接就可以在测试中模拟任何sql驱动程序的行为。使用它可以很方便的在编写单元测试的时候mock sql语句的执行结果。
安装
go get github.com/DATA-DOG/go-sqlmock
使用示例
这里使用的是go-sqlmock官方文档中提供的基础示例代码。在下面的代码中，我们实现一个recordStats函数用来记录用户浏览商品时产生的相关数据。具体实现的功能是在一个事务中进行以下两个SQL操作：

在products表中将当前商品的浏览次数+1
在product_viewers表中记录浏览当前商品的用户id

// app.go
package main

import &quot;database/sql&quot;

// recordStats 记录用户浏览产品信息
func recordStatus(db *sql.DB, userID, productID int64) (err error) {
    // 开启事务
    // 操作views和priduct_viewers两张表
    tx, err := db.Begin()
    if err != nil {
        return
    }

    defer func() {
        switch err {
        case nil :
            err = tx.Commit()
        default:
            tx.Rollback()
        }
    }()

    // 更新products表
    if _, err = tx.Exec(&quot;UPDATE products SET views = views + 1&quot;); err != nil {
        return
    }

    // product_viewers表中插入一条数据
    if _, err = tx.Exec(&quot;INSERT INTO product_viewers(user_id, product_id) VALUES (?, ?)&quot;, userID, productID); err != nil {
        return
    }

    return
}

func main() {
    // 注意：测试中并不需要真正的连接
    db, err := sql.Open(&quot;mysql&quot;, &quot;root@/blog&quot;)
    if err != nil {
        panic(err)
    }
    defer db.Close()

    // UserID为1的用户浏览了productID为5的产品
    if err = recordStats(db, 1 /*some user id*/, 5 /*some product id*/); err != nil {
        panic(err)
    }
}
现在我们需要为代码中的recordStats函数编写单元测试，但是又不想在测试过程中连接真实数据库进行测试。这个时候我们就可以像下面示例代码中那样，使用sqlmock工具去mock数据库操作。
package main

import (
    &quot;fmt&quot;
    &quot;testing&quot;

    &quot;github.com/DATA-DOG/go-sqlmock&quot;
)

// TestShouldUpdateStats sql执行成功的测试用例
func TestShouldUpdateStats(t *testing.T) {
    // mock一个*sql.DB对象，不需要连接真实的数据库
    db, mock, err := sqlmock.New()
    if err != nil {
        t.Fatalf(&quot;an error &#039;%s&#039; was not expected when opening a stub database connection&quot;, err)
    }
    defer db.Close()

    // mock执行指定SQL语句时的返回结果
    mock.ExpectBegin()
    mock.ExpectExec(&quot;UPDATE products&quot;).WillReturnResult(sqlmock.NewResult(1, 1))
    mock.ExpectExec(&quot;INSERT INTO product_viewers&quot;).WillArgs(2, 3).WithReturnResult(sqlmock.NewResult(1, 1))
    mock.ExpectCommit()

    // 将mock的DB对象传入我们的函数中
    if err = recordStats(db, 2, 3); err != nil {
        t.Errorf(&quot;error was not expected while updating stats: %s&quot;, err)
    }

    // 确保期望的结果都满足
    if err = mock.ExpectationsWereMet(); err != nil {
        t.Errorf(&quot;there are unfulfilled expectations: %s&quot;, err)
    }
}

// TestShouldRollbackStatUpdateOnFailure sql执行失败回滚的测试用例
func TestShouldRollbackStatUpdateOnFailure(t *testing.T) {
    db, mock, err := sqlmock.New()
    if err != nil {
        t.Fatalf(&quot;an error &#039;%s&#039; was not expected when opening a stub database connection&quot;, err)
    }
    defer db.Close()

    mock.ExpectBegin()
    mock.ExpectExec(&quot;UPDATE products&quot;).WillReturnResult(sqlmock.NewResult(1, 1))
    mock.ExpectExec(&quot;INSERT INTO product_viewers&quot;).WillArgs(2, 3).WillReturnError(fmt.Errorf(&quot;some error&quot;))
    mock.ExpectRollback()

    // now we execute our method
    if err = recordStats(db, 2, 3); err != nil {
        t.Errorf(&quot;was expecting an error, but there was none&quot;)
    }

    // we make sure that all expectations were met(我们确保所有的期望 都满足)
    if err = mock.ExpectationsWereMet(); err != nil {
        t.Errorf(&quot;there were unfulfilled expectations: %s&quot;, err)
    }
}
上面的代码中，定义了一个执行成功的测试用例和一个执行失败回滚的测试用例，确保我们代码中的每个逻辑分支都能被测试到，提高单元测试覆盖率的同时也保证了代码的健壮性。
miniredis
除了经常用到MySQL外，Redis在日常开发中也会经常用到。
miniredis是一个纯go实现的用于单元测试的redis server。它是一个简单易用的，基于内存的redis替代品，它具有真正的TCP接口，你可以把它当成redis版本的net/http/httptest
当我们为一些包含Redis操作的代码编写单元测试时就可以用它来mock Redis操作
安装
go get github.com/alicebob/miniredis/v2
使用示例
这里以github.com/go-redis/redis库为例，编写了一个包含若干个Redis操作的DoSomethingWithRedis函数
// redis_op.go
package miniredis_demo

import (
    &quot;context&quot;
    &quot;strings&quot;
    &quot;time&quot;

    &quot;github.com/go-redis/redis/v8&quot;
)

const (
    KeyValidWebsite = &quot;app:valid:website:list&quot;
)

func DoSomethingWithRedis(rdb *redis.Client, key string) bool {
    // 这里可以是对Redis操作的一些逻辑
    ctx := context.TODO()
    if !rdb.SisMember(ctx, KeyValidWebsite, key).Val() {
        return false
    }

    val, err := rdb.Get(ctx, key).Result()
    if err != nil {
        return false
    }

    if !strings.HasPrefix(val, &quot;https://&quot;) {
        val = &quot;https://&quot; + val
    }

    // 设置blog key五秒过期
    if err = rdb.Set(ctx, &quot;blog&quot;, val, 5 * time.Second).Err(); err != nil {
        return false
    }

    return true
}
下面代码使用miniredis库为DoSomethingWithRedis函数编写单元测试代码，其中miniredis不仅支持mock常用的Redis操作，还提供了很多实用的帮助函数，例如检查key的值是否与预期相等的s.CheckGet()和帮助检查key过期时间的s.FastForward()
// redis_op_test.go

package miniredis_demo

import (
    &quot;testing&quot;
    &quot;time&quot;

    &quot;github.com/alicebob/miniredis/v2&quot;
    &quot;github.com/go-redis/redis/v8&quot;
)

func TestDoSomethingWithRedis(t *testing.T) {
    // mock 一个redis server
    s, err := minireids.Run()
    if err != nil {
        panic(err)
    }
    defer s.Close()

    // 准备数据
    s.Set(&quot;cc&quot;, &quot;cc.com&quot;)
    s.SAdd(KeyValidWebsite, &quot;cc&quot;)

    // 连接mock的redis server
    rdb := redis.NewClient(&amp;redis.Options{
        // mock redis server 地址
        Addr: s.Addr(),
    })

    // 调用函数
    ok := DoSomethingWithRedis(rdb, &quot;cc&quot;)
    if !ok {
        t.Fatal()
    }

    // 可以手动检查redis中的值是否符合预期
    if got, err := s.Get(&quot;blog&quot;); err != nil || got != &quot;cc.com&quot; {
        t.Fatalf(&quot;&#039;blog&#039; has the wrong value&quot;)
    }

    // 也可以使用帮助工具检查
    s.CheckGet(t, &quot;blog&quot;, &quot;cc.com&quot;)

    // 过期检查
    s.FastForward(5 * time.Second)  // 快进5秒
    if s.Exists(&quot;blog&quot;) {
        t.Fatal(&quot;&#039;blog&#039; should not have existed anymore&quot;)
    }
}
总结
在日常工作开发中为代码编写单元测试时如何处理数据库依赖是最常见的问题，本文介绍了如何使用go-sqlmock和miniredis工具mock相关依赖。

golang/进阶/go-进阶-07---validator参数校验.content:
Go 进阶 07 - validator参数校验
在web开发中一个不可避免的环节就是对请求参数进行校验，通常我们对在代码中定义和请求参数相对应的模型(结构体)，借助模型绑定快捷地解析请求中的参数，例如gin框架中的Bind和ShouldBind系列的方法。本文就以gin框架的请求参数校验为例，介绍一些validator库的实用技巧。
gin框架使用的是github.com/go-playground/validator进行参数校验，目前已经支持github.com/go-playground/validator/v10了，我们需要在定义结构体时使用binding tag标识相关校验规则。
基本示例
首先来看gin框架内置使用validator做参数校验的基本示例。
package main

import (
    &quot;net/http&quot;

    &quot;github.com/gin-gonic/gin&quot;
)

type SignUpParam struct {
    Age         uint8   `json:&quot;age&quot; binding:&quot;gte=1, lte=130&quot;`
    Name        string  `json:&quot;name&quot; binding:&quot;required&quot;`
    Email       string  `json:&quot;email&quot; binding:&quot;required, email&quot;`
    Password    string  `json:&quot;password&quot; binding:&quot;required&quot;`
    RePassword  string  `josn:&quot;re_password&quot; binding:&quot;required, eqfield=Password&quot;`
}

func main() {
    r := gin.Default()

    r.POST(&quot;/signup&quot;, func(c *gin.Context) {
        var u SignUpParam
        if err := c.ShouldBind(&amp;u), err != nil {
            c.JSON(http/StatusOK, gin.H{
                &quot;msg&quot;:  err.Error(),
            })
            return
        }
        // 保存入库等业务逻辑代码...

        c.JSON(http.StatusOK, &quot;success&quot;)
    })

    _ := r.Run(&quot;:8999&quot;)
}
我们使用curl发送一个POST请求测试下
curl -H &quot;Content-type: application/json&quot; -X POST -d &#039;{&quot;name&quot;: &quot;q1mi&quot;, &quot;age&quot;: 18, &quot;email&quot;: &quot;123.com&quot;}&#039; http://127.0.0.1:8999/signup
输出结果
{&quot;msg&quot;:&quot;Key: &#039;SignUpParam.Email&#039; Error:Field validation for &#039;Email&#039; failed on the &#039;email&#039; tag\nKey: &#039;SignUpParam.Password&#039; Error:Field validation for &#039;Password&#039; failed on the &#039;required&#039; tag\nKey: &#039;SignUpParam.RePassword&#039; Error:Field validation for &#039;RePassword&#039; failed on the &#039;required&#039; tag&quot;}
从最终的输出结果可以看到validator的检验生效了，但是错误提示的字段不是特别友好，我们可能需要将它翻译成中文
翻译校验错误提示信息
validator库本身是支持国际化的，借助相应的语言包可以实现校验错误提示信息的自动翻译。下面的示例代码演示了如何将错误提示信息翻译成中文，翻译成其他语言的方法类似。
package  main
import (
    &quot;fmt&quot;
    &quot;net/http&quot;

    &quot;github.com/gin-gonic/gin&quot;
    &quot;github.com/gin-gonic/gin/binding&quot;
    &quot;github.com/go-playground/locales/en&quot;
    &quot;github.com/go-playground/locales/zh&quot;
    ut &quot;github.com/go-playground/universal-translator&quot;
    &quot;github.com/go-playground/validator/v10&quot;
    enTranslations &quot;github.com/go-playground/validator/v10/translations/en&quot;
    zhTranslations &quot;github.com/go-playground/validator/v10/translations/zh&quot;
)

// 定义一个全局翻译器T
var trans ut.Translator

// InitTrans 初始化翻译器
func InitTrans(locale string) (err error) {
    if v, ok := binding.Validator.Engine().(*validator.Validate); ok {
        // 中文翻译器
        zhT := zh.New()
        // 英文翻译器
        enT := en.New()

        // 第一个参数是备用(fallback)的语言环境
        // 后面的参数是应该支持的语言环境(支持多个)
        // uni := ut.New(zhT, zhT)也是可以的
        uni := ut.New(enT, zhT, enT)

        // locale通常取决于http请求头的&#039;Accept-Language&#039;
        var ok bool
        // 也可以使用uni.FindTranslator(...)传入多个locale进行查找
        trans, ok = uni.GetTranslator(locale)
        if !ok {
            return fmt.Errorf(&quot;uni.GetTranslator(%s) failed&quot;, locale)
        }

        // 注册翻译器
        switch locale {
            case &quot;en&quot;:
                err = enTranslations.RegisterDefaultTranslations(v, trans)
            case &quot;zh&quot;:
                err = zhTranslations.RegisterDefaultTranslations(v, trans)
            default:
                err = enTranslations.RegisterDefaultTranslations(v, trans)
        }
        return
    }
    return
}

type SignUpParam struct {
    Age         uint8   `json:&quot;age&quot; binding:&quot;gte=1,lte=130&quot;`
    Name        string  `json:&quot;name&quot; binding:&quot;required&quot;`
    Email       string  `json:&quot;email&quot; binding:&quot;required,email&quot;`
    Password    string  `json:&quot;password&quot; binding:&quot;required&quot;`
    RePassword  string  `json:&quot;re_password&quot; binding:&quot;required,eqfield=Password&quot;`
}

func main() {
    if err := InitTrans(&quot;zh&quot;); err != nil {
        fmt.Printf(&quot;init trans failed, err:%v\n&quot;, err)
        return
    }

    r := gin.Default()

    r.POST(&quot;/signup&quot;, func(c *gin.Context) {
        var u SignUpParam
        if err := c.ShouldBind(&amp;u); err != nil {
            // 获取validator.ValidationErrors类型的errors
            errs, ok := err.(validator.ValidationErrors)
            if !ok {
                // 非validator.ValidationErrors类型错误直接返回
                c.JSON(http.StatusOK, gin.H{
                    &quot;msg&quot;: err.Error(),
                })
                return
            }
            // validator.ValidationErrors类型错误则进行翻译
            c.JSON(http.Status, gin.H{
                &quot;msg&quot;: errs.Translate(trans),
            })
            return
        }
        // 保存入库等具体业务逻辑代码...

        c.JSON(http.StatusOK, &quot;success&quot;)
    })
    _ = r.Run(&quot;:8999&quot;)
}
我们使用curl发送一个POST请求测试下：
curl -H &quot;Content-type: application/json&quot; -X POST -d &#039;{&quot;name&quot;:&quot;q1mi&quot;, &quot;age&quot;:18, &quot;email&quot;:&quot;123.com&quot;}&#039; http://127.0.0.1:8999/signup
输出结果：
{&quot;msg&quot;: &quot;Key: &#039;SignUpParam.Email&#039; Error:Field validation for &#039;Email&#039; failed on the &#039;email&#039; tag\nKey: &#039;SignUpParam.Password&#039; Error:Field validation for &#039;Password&#039; failed on the &#039;required&#039; tag\nKey: &#039;SignUpParam.RePassword&#039; Error:Field validation for &#039;RePassword&#039; failed on the &#039;required&#039; tag&quot;}
从最终的输出结果可以看到validator的检验生效了，但是错误提示的字段不是很友好，我们可能需要将它翻译成中文
翻译校验错误提示信息
validator库本身是支持国际化的，借助相应的语言包可以实现校验错误提示信息的自动翻译，下面的示例代码演示了如何将错误提示信息翻译成中文，翻译成其他语言的方法类似
package main

import (
    &quot;fmt&quot;
    &quot;net/http&quot;

    &quot;github.com/gin-gonic/gin&quot;
	&quot;github.com/gin-gonic/gin/binding&quot;
	&quot;github.com/go-playground/locales/en&quot;
	&quot;github.com/go-playground/locales/zh&quot;
	ut &quot;github.com/go-playground/universal-translator&quot;
	&quot;github.com/go-playground/validator/v10&quot;
	enTranslations &quot;github.com/go-playground/validator/v10/translations/en&quot;
	zhTranslations &quot;github.com/go-playground/validator/v10/translations/zh&quot;
)

// 定义一个全局翻译器T
var trans ut.Translator

// 初始化翻译器
func InitTrans(locale string) (err error) {
    // 修改gin框架中的Validator引擎属性，实现自定制
    if v, ok := binding.Validator.Engine().(*validator.Validate); ok {

        zhT := zh.New() // 中文翻译器
		enT := en.New() // 英文翻译器

		// 第一个参数是备用（fallback）的语言环境
		// 后面的参数是应该支持的语言环境（支持多个）
		// uni := ut.New(zhT, zhT) 也是可以的
		uni := ut.New(enT, zhT, enT)

		// locale 通常取决于 http 请求头的 &#039;Accept-Language&#039;
		var ok bool
		// 也可以使用 uni.FindTranslator(...) 传入多个locale进行查找
		trans, ok = uni.GetTranslator(locale)
		if !ok {
			return fmt.Errorf(&quot;uni.GetTranslator(%s) failed&quot;, locale)
		}

		// 注册翻译器
		switch locale {
		case &quot;en&quot;:
			err = enTranslations.RegisterDefaultTranslations(v, trans)
		case &quot;zh&quot;:
			err = zhTranslations.RegisterDefaultTranslations(v, trans)
		default:
			err = enTranslations.RegisterDefaultTranslations(v, trans)
		}
		return
    }
    return
}

type SignUpParam struct {
	Age        uint8  `json:&quot;age&quot; binding:&quot;gte=1,lte=130&quot;`
	Name       string `json:&quot;name&quot; binding:&quot;required&quot;`
	Email      string `json:&quot;email&quot; binding:&quot;required,email&quot;`
	Password   string `json:&quot;password&quot; binding:&quot;required&quot;`
	RePassword string `json:&quot;re_password&quot; binding:&quot;required,eqfield=Password&quot;`
}

func main() {
	if err := InitTrans(&quot;zh&quot;); err != nil {
		fmt.Printf(&quot;init trans failed, err:%v\n&quot;, err)
		return
	}

	r := gin.Default()

	r.POST(&quot;/signup&quot;, func(c *gin.Context) {
		var u SignUpParam
		if err := c.ShouldBind(&amp;u); err != nil {
			// 获取validator.ValidationErrors类型的errors
			errs, ok := err.(validator.ValidationErrors)
			if !ok {
				// 非validator.ValidationErrors类型错误直接返回
				c.JSON(http.StatusOK, gin.H{
					&quot;msg&quot;: err.Error(),
				})
				return
			}
			// validator.ValidationErrors类型错误则进行翻译
			c.JSON(http.StatusOK, gin.H{
				&quot;msg&quot;:errs.Translate(trans),
			})
			return
		}
		// 保存入库等具体业务逻辑代码...

		c.JSON(http.StatusOK, &quot;success&quot;)
	})

	_ = r.Run(&quot;:8999&quot;)
}
同样的请求再来一次
curl -H &quot;Content-type: application/json&quot; -X POST -d &#039;{&quot;name&quot;:&quot;q1mi&quot;,&quot;age&quot;:18,&quot;email&quot;:&quot;123.com&quot;}&#039; http://127.0.0.1:8999/signup
这次的输出结果如下
{&quot;msg&quot;:{&quot;SignUpParam.Email&quot;:&quot;Email必须是一个有效的邮箱&quot;,&quot;SignUpParam.Password&quot;:&quot;Password为必填字段&quot;,&quot;SignUpParam.RePassword&quot;:&quot;RePassword为必填字段&quot;}}
自定义错误提示信息的字段名
上面的错误提示看起来可以了，但是还是差点意思，首先是错误提示中的字段并不是请求中使用的字段，例如：RePassword使我们后端定义的结构体中的字段名，而请求中使用的是re_password字段。如何使错误提示中的字段使用自定义的名称，例如json tag指定的值？
只需要在初始化翻译器的时候像下面一样添加一个获取json tag的自定义方法即可。
// InitTrans 初始化翻译器
func InitTrans(locale string) (err error) {
	// 修改gin框架中的Validator引擎属性，实现自定制
	if v, ok := binding.Validator.Engine().(*validator.Validate); ok {

		// 注册一个获取json tag的自定义方法
		v.RegisterTagNameFunc(func(fld reflect.StructField) string {
			name := strings.SplitN(fld.Tag.Get(&quot;json&quot;), &quot;,&quot;, 2)[0]
			if name == &quot;-&quot; {
				return &quot;&quot;
			}
			return name
		})

		zhT := zh.New() // 中文翻译器
		enT := en.New() // 英文翻译器

		// 第一个参数是备用（fallback）的语言环境
		// 后面的参数是应该支持的语言环境（支持多个）
		// uni := ut.New(zhT, zhT) 也是可以的
		uni := ut.New(enT, zhT, enT)

		// ... liwenzhou.com ...
}
再尝试发请求，看一下效果：
{&quot;msg&quot;:{&quot;SignUpParam.email&quot;:&quot;email必须是一个有效的邮箱&quot;,&quot;SignUpParam.password&quot;:&quot;password为必填字段&quot;,&quot;SignUpParam.re_password&quot;:&quot;re_password为必填字段&quot;}}
可以看到现在错误提示信息中使用的就是我们结构体中json tag设置的名称了
但是还是有点瑕疵，那就是最终的错误提示信息中心还是有我们后端定义的结构体名称–SignUpParam，这个名称其实是不需要随错误提示返回给前端的，前端并不需要这个值。我们需要想办法把它去掉。
这里参考github.com/go-playground/validator/issues/633#issuecomment-654382345提供的方法，定义一个去掉结构体名称前缀的自定义方法：
func removeTopStruct(fields map[string]string) map[string]string {
	res := map[string]string{}
	for field, err := range fields {
		res[field[strings.Index(field, &quot;.&quot;)+1:]] = err
	}
	return res
}
我们在代码中使用上述函数将翻译后的errors做一下处理即可：
if err := c.ShouldBind(&amp;u); err != nil {
	// 获取validator.ValidationErrors类型的errors
	errs, ok := err.(validator.ValidationErrors)
	if !ok {
		// 非validator.ValidationErrors类型错误直接返回
		c.JSON(http.StatusOK, gin.H{
			&quot;msg&quot;: err.Error(),
		})
		return
	}
	// validator.ValidationErrors类型错误则进行翻译
	// 并使用removeTopStruct函数去除字段名中的结构体名称标识
	c.JSON(http.StatusOK, gin.H{
		&quot;msg&quot;: removeTopStruct(errs.Translate(trans)),
	})
	return
}
看一下最终的效果
{&quot;msg&quot;:{&quot;email&quot;:&quot;email必须是一个有效的邮箱&quot;,&quot;password&quot;:&quot;password为必填字段&quot;,&quot;re_password&quot;:&quot;re_password为必填字段&quot;}}
这一次看起来就比较符合我们预期的标准了。
自定义结构体校验方法
上面的校验还是有点小问题，就是当涉及到一些复杂的校验规则，比如re_password字段需要与password字段的值相等这样的校验规则，我们的自定义错误提示字段名称方法就不能很好解决错误提示信息中的其他字段名称了。
curl -H &quot;Content-type: application/json&quot; -X POST -d &#039;{&quot;name&quot;:&quot;q1mi&quot;,&quot;age&quot;:18,&quot;email&quot;:&quot;123.com&quot;,&quot;password&quot;:&quot;123&quot;,&quot;re_password&quot;:&quot;321&quot;}&#039; http://127.0.0.1:8999/signup
最后输出的错误提示信息如下
{&quot;msg&quot;:{&quot;email&quot;:&quot;email必须是一个有效的邮箱&quot;,&quot;re_password&quot;:&quot;re_password必须等于Password&quot;}}
可以看到re_password字段的提示信息中还是出现了Password这个结构体字段名称。这有点小小的遗憾，毕竟自定义字段名称的方法不能影响被当成param传入的值。
此时如果想要追求更好的提示效果，将上面的Password字段也改为和json tag一致的名称，就需要我们自定义结构体校验的方法。
例如，我们为SignUpParam自定义一个校验方法如下：
// SignUpParamStructLevelValidation 自定义SignUpParam结构体校验函数
func SignUpParamStructLevelValidation(sl validator.StructLevel) {
	su := sl.Current().Interface().(SignUpParam)

	if su.Password != su.RePassword {
		// 输出错误提示信息，最后一个参数就是传递的param
		sl.ReportError(su.RePassword, &quot;re_password&quot;, &quot;RePassword&quot;, &quot;eqfield&quot;, &quot;password&quot;)
	}
}
然后在初始化校验器的函数中注册该自定义校验方法即可：
func InitTrans(locale string) (err error) {
	// 修改gin框架中的Validator引擎属性，实现自定制
	if v, ok := binding.Validator.Engine().(*validator.Validate); ok {

		// ... liwenzhou.com ...

		// 为SignUpParam注册自定义校验方法
		v.RegisterStructValidation(SignUpParamStructLevelValidation, SignUpParam{})

		zhT := zh.New() // 中文翻译器
		enT := en.New() // 英文翻译器

		// ... liwenzhou.com ...
}
最终再请求一次，看一下效果：
{&quot;msg&quot;:{&quot;email&quot;:&quot;email必须是一个有效的邮箱&quot;,&quot;re_password&quot;:&quot;re_password必须等于password&quot;}}
这一次re_password字段的错误提示信息就符合我们预期了。
自定义字段校验方法
除了上面介绍到的自定义结构体校验方法，validator还支持为某个字段自定义校验方法，并使用RegisterValidation()注册到校验器实例中。
接下来我们来为SignUpParam添加一个需要使用自定义校验方法checkDate做参数校验的字段Date。
type SignUpParam struct {
	Age        uint8  `json:&quot;age&quot; binding:&quot;gte=1,lte=130&quot;`
	Name       string `json:&quot;name&quot; binding:&quot;required&quot;`
	Email      string `json:&quot;email&quot; binding:&quot;required,email&quot;`
	Password   string `json:&quot;password&quot; binding:&quot;required&quot;`
	RePassword string `json:&quot;re_password&quot; binding:&quot;required,eqfield=Password&quot;`
	// 需要使用自定义校验方法checkDate做参数校验的字段Date
	Date       string `json:&quot;date&quot; binding:&quot;required,datetime=2006-01-02,checkDate&quot;`
}
其中datetime=2006-01-02是内置的用于校验日期类参数是否满足指定格式要求的tag。 如果传入的date参数不满足2006-01-02这种格式就会提示如下错误：
{&quot;msg&quot;:{&quot;date&quot;:&quot;date的格式必须是2006-01-02&quot;}}
针对date字段除了内置的datetime=2006-01-02提供的格式要求外，假设我们还要求该字段的时间必须是一个未来的时间（晚于当前时间），像这样针对某个字段的特殊校验需求就需要我们使用自定义字段校验方法了。
首先我们要在需要执行自定义校验的字段后面添加自定义tag，这里使用的是checkDate，注意使用英文分号分隔开。
// customFunc 自定义字段级别校验方法
func customFunc(fl validator.FieldLevel) bool {
	date, err := time.Parse(&quot;2006-01-02&quot;, fl.Field().String())
	if err != nil {
		return false
	}
	if date.Before(time.Now()) {
		return false
	}
	return true
}
定义好了字段及其自定义校验方法后，就需要将它们联系起来并注册到我们的校验器实例中。
// 在校验器注册自定义的校验方法
if err := v.RegisterValidation(&quot;checkDate&quot;, customFunc); err != nil {
	return err
}
这样，我们就可以对请求参数中date字段执行自定义的checkDate进行校验了。 我们发送如下请求测试一下：
curl -H &quot;Content-type: application/json&quot; -X POST -d &#039;{&quot;name&quot;:&quot;q1mi&quot;,&quot;age&quot;:18,&quot;email&quot;:&quot;123@qq.com&quot;,&quot;password&quot;:&quot;123&quot;, &quot;re_password&quot;: &quot;123&quot;, &quot;date&quot;:&quot;2020-01-02&quot;}&#039; http://127.0.0.1:8999/signup
此时得到的响应结果是：
{&quot;msg&quot;:{&quot;date&quot;:&quot;Key: &#039;SignUpParam.date&#039; Error:Field validation for &#039;date&#039; failed on the &#039;checkDate&#039; tag&quot;}}
这…自定义字段级别的校验方法的错误提示信息很“简单粗暴”，和我们上面的中文提示风格有出入，必须想办法搞定它呀！
自定义翻译方法
我们现在需要为自定义字段校验方法提供一个自定义的翻译方法，从而实现该字段错误提示信息的自定义显示。
// registerTranslator 为自定义字段添加翻译功能
func registerTranslator(tag string, msg string) validator.RegisterTranslationsFunc {
	return func(trans ut.Translator) error {
		if err := trans.Add(tag, msg, false); err != nil {
			return err
		}
		return nil
	}
}

// translate 自定义字段的翻译方法
func translate(trans ut.Translator, fe validator.FieldError) string {
	msg, err := trans.T(fe.Tag(), fe.Field())
	if err != nil {
		panic(fe.(error).Error())
	}
	return msg
}
定义好了相关翻译方法之后，我们在InitTrans函数中通过调用RegisterTranslation()方法来注册我们自定义的翻译方法。
// InitTrans 初始化翻译器
func InitTrans(locale string) (err error) {
	// ...liwenzhou.com...

		// 注册翻译器
		switch locale {
		case &quot;en&quot;:
			err = enTranslations.RegisterDefaultTranslations(v, trans)
		case &quot;zh&quot;:
			err = zhTranslations.RegisterDefaultTranslations(v, trans)
		default:
			err = enTranslations.RegisterDefaultTranslations(v, trans)
		}
		if err != nil {
			return err
		}
		// 注意！因为这里会使用到trans实例
		// 所以这一步注册要放到trans初始化的后面
		if err := v.RegisterTranslation(
			&quot;checkDate&quot;,
			trans,
			registerTranslator(&quot;checkDate&quot;, &quot;{0}必须要晚于当前日期&quot;),
			translate,
		); err != nil {
			return err
		}
		return
	}
	return
}
这样再次尝试发送请求，就能得到想要的错误提示信息了。
{&quot;msg&quot;:{&quot;date&quot;:&quot;date必须要晚于当前日期&quot;}}
总结
本文总结的gin框架中validator的使用技巧同样也适用于直接使用validator库，区别仅仅在于我们配置的是gin框架中的校验器还是由validator.New()创建的校验器。同时使用validator库确实能够在一定程度上减少我们的编码量，但是它不太可能完美解决我们所有需求，所以你需要找到两者之间的平衡点。

golang/进阶/go-进阶-08---grpc入门.content:
Go 进阶 08 - gRPC入门
RPC是什么
在分布式计算，远程过程调用(英语：Remote Procedure Call，缩写为RPC)是一个计算机通信协议。该协议允许运行于一台计算机的程序调用另一个地址空间(通常为一个开放网络的一台计算机)的子程序，而程序员就像调用本地程序一样，无需额外地为这个交互作用编程(无需关注细节)。RPC是一种服务器-客户端(Client/Server)模式，经典实现是通过一个发送请求-接收回应进行信息交互的系统
gRPC是什么
gRPC是一种现代化开源的高性能RPC框架，能够运行于任意环境之中。最初由谷歌进行开发。它使用HTTP/2作为传输协议。
在gRPC里，客户端可以像调用本地方法一样直接调用其他机器上的服务端应用程序的方法，帮助你更容易创建分布式应用程序和服务。和许多RPC系统一样，gRPC是基于定义一个服务，指定一个可以远程调用的带有参数和返回类型的方法。在服务端程序中实现这个接口并且运行gRPC服务处理客户端调用。在客户端，有一个stub提供和服务端相同的方法。
为什么要用gRPC
使用gRPC，我们可以一次性的在一个.proto文件中定义服务并使用任何支持它的语言去实现客户端和服务端，反过来，它们可以应用在各种场景中，从Google的服务器到你自己的平板电脑–gRPC帮你解决了不同语言及环境间通信的复杂性。使用protocol buffers还能获得其他好处，包括高效的序列号，简单的IDL以及容易进行接口更新。总之一句话，使用gRPC能让我们更容易编写跨语言的分布式代码
安装gRPC
安装gRPC
go get -u google.golang.org/grpc
安装Protocol Buffers V3
安装用于生成gRPC服务代码的协议编译器，最简单的方法是从下面的链接：github.com/google/protobuf/releases下载适合你平台的预编译好的二进制文件(protoc-&lt;version&gt;-&lt;platform&gt;.zip)
下载完，执行下面步骤：

解压下载好的文件
把protoc二进制文件的路径加到环境变量中

接下来执行下面的命令安装protoc的Go插件
go get -u github.com/golang/protobuf/protoc-gen-go
编译插件protoc-gen-go将会安装到$GOBIN，默认是$GOPATH/bin，它必须在你的$PATH中以便协议编译器protoc能够找到它
gRPC开发分三步

编写.proto文件，生成指定语言源代码
编写服务端代码
编写客户端代码

gRPC入门实例
编写proto代码
gRPC是基于Protocol Buffers。
Protocol Buffers是一种与语言无关，与平台无关的可扩展机制，用于序列化结构化数据。使用Protocol Buffers可以一次定义结构化的数据，然后可以使用特殊生成的源代码轻松地在各种数据流中使用各种语言编写和读取结构化数据。
关于Protocol Buffers的教程可以自行网上搜索。
syntax = &quot;proto3&quot;; // 版本声明，使用Protocol Buffers v3版本

package pb; // 包名


// 定义一个打招呼服务
service Greeter {
    // SayHello 方法
    rpc SayHello (HelloRequest) returns (HelloReply) {}
}

// 包含人名的一个请求消息
message HelloRequest {
    string name = 1;
}

// 包含问候语的响应消息
message HelloReply {
    string message = 1;
}
执行下面命令，生成go语言源代码
protoc -I helloworld/ helloworld/pb/helloworld.proto --go_out=plugins=grpc:helloworld
在gRPC_demo/helloworld/pb目录下会生成helloworld.pb.go文件
编写Server端Go代码
package main

import (
	&quot;fmt&quot;
	&quot;net&quot;

	pb &quot;gRPC_demo/helloworld/pb&quot;
	&quot;golang.org/x/net/context&quot;
	&quot;google.golang.org/grpc&quot;
	&quot;google.golang.org/grpc/reflection&quot;
)

type server struct{}

func (s *server) SayHello(ctx context.Context, in *pb.HelloRequest) (*pb.HelloReply, error) {
	return &amp;pb.HelloReply{Message: &quot;Hello &quot; + in.Name}, nil
}

func main() {
	// 监听本地的8972端口
	lis, err := net.Listen(&quot;tcp&quot;, &quot;:8972&quot;)
	if err != nil {
		fmt.Printf(&quot;failed to listen: %v&quot;, err)
		return
	}
	s := grpc.NewServer() // 创建gRPC服务器
	pb.RegisterGreeterServer(s, &amp;server{}) // 在gRPC服务端注册服务

	reflection.Register(s) //在给定的gRPC服务器上注册服务器反射服务
	// Serve方法在lis上接受传入连接，为每个连接创建一个ServerTransport和server的goroutine。
	// 该goroutine读取gRPC请求，然后调用已注册的处理程序来响应它们。
	err = s.Serve(lis)
	if err != nil {
		fmt.Printf(&quot;failed to serve: %v&quot;, err)
		return
	}
}
将上面的代码保存到gRPC_demo/helloworld/server/server.go文件中，编译并执行
cd helloworld/server
go build
./server
编写Client端Go代码
package main

import (
	&quot;context&quot;
	&quot;fmt&quot;

	pb &quot;gRPC_demo/helloworld/pb&quot;
	&quot;google.golang.org/grpc&quot;
)

func main() {
	// 连接服务器
	conn, err := grpc.Dial(&quot;:8972&quot;, grpc.WithInsecure())
	if err != nil {
		fmt.Printf(&quot;faild to connect: %v&quot;, err)
	}
	defer conn.Close()

	c := pb.NewGreeterClient(conn)
	// 调用服务端的SayHello
	r, err := c.SayHello(context.Background(), &amp;pb.HelloRequest{Name: &quot;q1mi&quot;})
	if err != nil {
		fmt.Printf(&quot;could not greet: %v&quot;, err)
	}
	fmt.Printf(&quot;Greeting: %s !\n&quot;, r.Message)
}
将上述代码保存到gRPC_demo/helloworld/client/client.go文件中，编译并执行
cd helloworld/client/
go build
./client
得到输出如下(注意要县启动server端再启动client端):
$ ./client
Greeting: Hello q1mi!
gRPC跨语言调用
接下来，我们演示一下如何使用gRPC实现跨语言的RPC调用
我们使用Python语言编写Client，然后向上面使用Go语言编写的server发送RPC请求
生成Python代码
在gRPC_demo目录执行下面的命令
python -m grpc_tools.protoc -I helloworld/pb/ --python_out=helloworld/client/ --grpc_python_out=helloworld/client/ helloworld/pb/helloworld.proto
上面的命令会在gRPC_demo/helloworld/client/目录生成如下两个Python文件：
helloworld_pb2.py
helloworld_pb2_grpc.py
编写Python版Client
在gRPC_demo/helloworld/client/目录创建client.py文件，内容如下

# coding=utf-8

import logging

import grpc

import helloworld_pb2
import helloworld_pb2_grpc


def run():
    # 注意(gRPC Python Team): .close()方法在channel上是可用的。
    # 并且应该在with语句不符合代码需求的情况下使用。
    with grpc.insecure_channel(&#039;localhost:8972&#039;) as channel:
        stub = helloworld_pb2_grpc.GreeterStub(channel)
        response = stub.SayHello(helloworld_pb2.HelloRequest(name=&#039;q1mi&#039;))
    print(&quot;Greeter client received: {}!&quot;.format(response.message))


if __name__ == &#039;__main__&#039;:
    logging.basicConfig()
    run()
将上面的代码保存执行，得到输出结果如下
gRPC_demo $ python helloworld/client/client.py
Greeter client received: Hello q1mi!
这里我们就实现了，使用python代码编写的client去调用Go语言版本的server。

golang/进阶/go-进阶-09---web框架-gin入门.content:
Go 进阶 09 — Web 框架 Gin 入门
Gin 概述
Gin 是 Go 最流行的 Web 框架，以高性能和轻量著称：
import &quot;github.com/gin-gonic/gin&quot;

r := gin.Default()
r.GET(&quot;/ping&quot;, func(c *gin.Context) {
    c.JSON(200, gin.H{
        &quot;message&quot;: &quot;pong&quot;,
    })
})
r.Run() // 默认 :8080

























特性说明路由支持 RESTful、路由组、参数路由中间件全局/路由级中间件、链式处理参数绑定JSON/Form/URI 自动绑定和校验渲染JSON/XML/HTML/Protobuf/YAML
路由
基础路由
r.GET(&quot;/user&quot;, handler)
r.POST(&quot;/user&quot;, handler)
r.PUT(&quot;/user/:id&quot;, handler)
r.DELETE(&quot;/user/:id&quot;, handler)
r.PATCH(&quot;/user/:id&quot;, handler)
r.Any(&quot;/health&quot;, handler)  // 所有方法
路径参数
r.GET(&quot;/user/:id&quot;, func(c *gin.Context) {
    id := c.Param(&quot;id&quot;)   // 路径参数
    name := c.Query(&quot;name&quot;) // URL 查询参数
    c.JSON(200, gin.H{&quot;id&quot;: id, &quot;name&quot;: name})
})
// GET /user/123?name=alice → {&quot;id&quot;:&quot;123&quot;,&quot;name&quot;:&quot;alice&quot;}
通配符路由
r.GET(&quot;/files/*path&quot;, func(c *gin.Context) {
    path := c.Param(&quot;path&quot;) // 包含前导 /
    c.String(200, &quot;file: %s&quot;, path)
})
// GET /files/a/b/c.txt → &quot;file: /a/b/c.txt&quot;
路由组
v1 := r.Group(&quot;/api/v1&quot;)
{
    v1.GET(&quot;/users&quot;, listUsers)
    v1.POST(&quot;/users&quot;, createUser)
    v1.GET(&quot;/users/:id&quot;, getUser)
}

v2 := r.Group(&quot;/api/v2&quot;)
{
    v2.GET(&quot;/users&quot;, listUsersV2)
}
请求参数绑定
type CreateUserRequest struct {
    Name  string `json:&quot;name&quot; form:&quot;name&quot; binding:&quot;required&quot;`
    Email string `json:&quot;email&quot; form:&quot;email&quot; binding:&quot;required,email&quot;`
    Age   int    `json:&quot;age&quot; form:&quot;age&quot; binding:&quot;gte=0,lte=150&quot;`
}

r.POST(&quot;/user&quot;, func(c *gin.Context) {
    var req CreateUserRequest
    if err := c.ShouldBindJSON(&amp;req); err != nil {
        c.JSON(400, gin.H{&quot;error&quot;: err.Error()})
        return
    }
    c.JSON(200, req)
})
不同绑定方式
c.ShouldBindJSON(&amp;req)     // JSON body
c.ShouldBindQuery(&amp;req)    // URL 查询参数
c.ShouldBindForm(&amp;req)     // 表单
c.ShouldBindUri(&amp;req)      // URI 路径参数
c.ShouldBind(&amp;req)         // 自动判断 Content-Type
中间件
// 全局中间件
r.Use(gin.Logger())
r.Use(gin.Recovery())

// 自定义中间件
func AuthMiddleware() gin.HandlerFunc {
    return func(c *gin.Context) {
        token := c.GetHeader(&quot;Authorization&quot;)
        if token == &quot;&quot; {
            c.AbortWithStatusJSON(401, gin.H{&quot;error&quot;: &quot;unauthorized&quot;})
            return
        }
        // 验证 token...
        c.Set(&quot;user_id&quot;, &quot;123&quot;)
        c.Next()  // 继续执行
    }
}

r.GET(&quot;/profile&quot;, AuthMiddleware(), func(c *gin.Context) {
    userID := c.GetString(&quot;user_id&quot;)
    c.JSON(200, gin.H{&quot;user_id&quot;: userID})
})
路由组中间件
api := r.Group(&quot;/api&quot;)
api.Use(AuthMiddleware())
{
    api.GET(&quot;/profile&quot;, profile)
    api.PUT(&quot;/settings&quot;, updateSettings)
}
响应格式
// JSON
c.JSON(200, gin.H{&quot;key&quot;: &quot;value&quot;})
c.JSON(200, &amp;user)  // 结构体自动序列化

// XML
c.XML(200, gin.H{&quot;key&quot;: &quot;value&quot;})

// YAML
c.YAML(200, gin.H{&quot;key&quot;: &quot;value&quot;})

// 字符串
c.String(200, &quot;Hello %s&quot;, name)

// 文件
c.File(&quot;./static/logo.png&quot;)

// 重定向
c.Redirect(301, &quot;/new-path&quot;)
静态文件服务
r.Static(&quot;/static&quot;, &quot;./public&quot;)
r.StaticFile(&quot;/favicon.ico&quot;, &quot;./public/favicon.ico&quot;)
r.StaticFS(&quot;/assets&quot;, http.Dir(&quot;./assets&quot;))
