golang/进阶/go-进阶-11---json-处理.content:
Go 进阶 11 — JSON 处理
encoding/json 基础
import &quot;encoding/json&quot;

type User struct {
    ID    int    `json:&quot;id&quot;`
    Name  string `json:&quot;name&quot;`
    Email string `json:&quot;email,omitempty&quot;`  // 空值时忽略
    Role  string `json:&quot;-&quot;`               // 忽略该字段
}
Marshal（序列化）
u := User{ID: 1, Name: &quot;Alice&quot;, Email: &quot;alice@example.com&quot;, Role: &quot;admin&quot;}

// 到 []byte
bytes, err := json.Marshal(u)
// bytes = {&quot;id&quot;:1,&quot;name&quot;:&quot;Alice&quot;,&quot;email&quot;:&quot;alice@example.com&quot;}

// 格式化输出
bytes, err := json.MarshalIndent(u, &quot;&quot;, &quot;  &quot;)
// {
//   &quot;id&quot;: 1,
//   &quot;name&quot;: &quot;Alice&quot;,
//   &quot;email&quot;: &quot;alice@example.com&quot;
// }
Unmarshal（反序列化）
data := []byte(`{&quot;id&quot;:1,&quot;name&quot;:&quot;Alice&quot;}`)

var u User
if err := json.Unmarshal(data, &amp;u); err != nil {
    // 处理错误
}
fmt.Println(u.Name) // &quot;Alice&quot;
Struct Tag 详解
type Config struct {
    // 重命名字段
    ServerName string `json:&quot;server_name&quot;`

    // 空值时忽略
    Description string `json:&quot;description,omitempty&quot;`

    // 忽略该字段
    SecretKey string `json:&quot;-&quot;`

    // 字符串转数字
    Port int `json:&quot;port,string&quot;`  // `&quot;port&quot;: &quot;8080&quot;` → Port = 8080

    // 强制数字/布尔作为字符串
    Enabled bool `json:&quot;enabled,string&quot;`  // `&quot;enabled&quot;: &quot;true&quot;`

    // 嵌入字段展平
    Base
    // 嵌套对象
    Extra ExtraConfig `json:&quot;extra&quot;`
}

type Base struct {
    Version string `json:&quot;version&quot;`
}

// 输出展平版本字段
// {&quot;server_name&quot;:&quot;...&quot;, &quot;version&quot;:&quot;1.0&quot;, &quot;extra&quot;:{...}}
动态 JSON
interface{} 处理
var data interface{}
json.Unmarshal([]byte(`{&quot;name&quot;:&quot;Alice&quot;,&quot;age&quot;:30}`), &amp;data)

m := data.(map[string]interface{})
name := m[&quot;name&quot;].(string)  // &quot;Alice&quot;
age := m[&quot;age&quot;].(float64)   // JSON 数字默认解析为 float64
json.RawMessage — 延迟解析
type Response struct {
    Code    int              `json:&quot;code&quot;`
    Message string           `json:&quot;message&quot;`
    Data    json.RawMessage  `json:&quot;data&quot;`  // 暂不解析
}

// 先解析外层，再根据类型解析 Data
var resp Response
json.Unmarshal(bytes, &amp;resp)

switch {
case resp.Code == 200:
    var users []User
    json.Unmarshal(resp.Data, &amp;users)
}
json.Decoder — 流式读取
// 适合大文件/HTTP 流
file, _ := os.Open(&quot;large.json&quot;)
defer file.Close()

decoder := json.NewDecoder(file)
for {
    var user User
    if err := decoder.Decode(&amp;user); err == io.EOF {
        break
    } else if err != nil {
        log.Fatal(err)
    }
    fmt.Println(user.Name)
}
自定义 Marshal/Unmarshal
type Duration time.Duration

// 自定义序列化：纳秒 → 可读字符串
func (d Duration) MarshalJSON() ([]byte, error) {
    return json.Marshal(time.Duration(d).String())
}

// 自定义反序列化：字符串 → 纳秒
func (d *Duration) UnmarshalJSON(b []byte) error {
    var s string
    if err := json.Unmarshal(b, &amp;s); err != nil {
        return err
    }
    dur, err := time.ParseDuration(s)
    if err != nil {
        return err
    }
    *d = Duration(dur)
    return nil
}
性能优化
预分配
// ❌ 慢：反复扩容
var buf bytes.Buffer
encoder := json.NewEncoder(&amp;buf)
for _, u := range users {
    encoder.Encode(u)
}

// ✅ 快：预分配
buf := bytes.NewBuffer(make([]byte, 0, len(users)*100))  // 估算大小
编码器复用
// 复用 Encoder
var bufPool = sync.Pool{
    New: func() interface{} {
        return &amp;bytes.Buffer{}
    },
}

buf := bufPool.Get().(*bytes.Buffer)
buf.Reset()
json.NewEncoder(buf).Encode(data)
第三方库对比






























