golang/进阶/go-进阶-12---错误处理进阶.content:
Go 进阶 12 — 错误处理进阶

基础错误处理见 Go 基础 12 - 错误处理 defer-panic-recover。

error 接口
Go 的错误是一个接口，而非异常：
type error interface {
    Error() string
}
// 任何实现了 Error() 方法的类型都可以作为错误
type MyError struct {
    Code    int
    Message string
}

func (e *MyError) Error() string {
    return fmt.Sprintf(&quot;code=%d: %s&quot;, e.Code, e.Message)
}
自定义错误类型
简单的 sentinel error
var ErrNotFound = errors.New(&quot;not found&quot;)
var ErrPermission = errors.New(&quot;permission denied&quot;)

func GetUser(id int) (*User, error) {
    if id &lt;= 0 {
        return nil, ErrNotFound
    }
    // ...
}
带上下文的错误
type AppError struct {
    Code    int
    Message string
    Err     error  // 包装的原始错误
}

func (e *AppError) Error() string {
    return fmt.Sprintf(&quot;code=%d: %s (%v)&quot;, e.Code, e.Message, e.Err)
}

func (e *AppError) Unwrap() error {
    return e.Err
}
errors.Is 与 errors.As
Go 1.13+ 引入了错误链的检查：
errors.Is — 判断错误类型
// 检查错误链中是否有 ErrNotFound
if errors.Is(err, ErrNotFound) {
    fmt.Println(&quot;resource not found&quot;)
}

// 自定义 Unwrap 方法的错误同样支持
if errors.Is(err, io.EOF) {
    fmt.Println(&quot;end of file&quot;)
}
errors.As — 获取具体错误值
// 从错误链中查找并提取 *MyError 类型的错误
var myErr *MyError
if errors.As(err, &amp;myErr) {
    fmt.Printf(&quot;code=%d, message=%s\n&quot;, myErr.Code, myErr.Message)
}
错误包装（fmt.Errorf + %w）
// 包装错误：建立错误链
func ReadConfig(path string) error {
    data, err := os.ReadFile(path)
    if err != nil {
        return fmt.Errorf(&quot;read config %s: %w&quot;, path, err)
    }
    // ...
}
wrap vs 不 wrap
// ✅ %w 包装（可解开）
return fmt.Errorf(&quot;read file: %w&quot;, err)
errors.Is(err, os.ErrNotExist)  // true

// ❌ %v 不包装（丢失原始错误信息）
return fmt.Errorf(&quot;read file: %v&quot;, err)
errors.Is(err, os.ErrNotExist)  // false，检查不通过
多层包装
func LoadConfig(path string) (*Config, error) {
    data, err := os.ReadFile(path)
    if err != nil {
        return nil, fmt.Errorf(&quot;load config: %w&quot;, err)
    }

    var cfg Config
    if err := json.Unmarshal(data, &amp;cfg); err != nil {
        return nil, fmt.Errorf(&quot;parse config: %w&quot;, err)
    }
    return &amp;cfg, nil
}

// 调用方可以一直追溯到根因
err := LoadConfig(&quot;/etc/config.json&quot;)
fmt.Println(err)                            // &quot;load config: parse config: unexpected end of JSON input&quot;
fmt.Println(errors.Is(err, io.ErrUnexpectedEOF))  // true
Sentinel Error 模式
// 定义 sentinel error
var (
    ErrNotFound      = errors.New(&quot;resource not found&quot;)
    ErrAlreadyExists = errors.New(&quot;resource already exists&quot;)
    ErrForbidden     = errors.New(&quot;permission denied&quot;)
)

// 在 API 中返回
func (s *Store) Get(id int) (*Item, error) {
    item, ok := s.data[id]
    if !ok {
        return nil, fmt.Errorf(&quot;store.Get(%d): %w&quot;, id, ErrNotFound)
    }
    return &amp;item, nil
}
使用 sentinel error 的注意事项
// ❌ 避免：导出具体的 sentinel
var ErrSpecific = errors.New(&quot;specific db error&quot;)
func Get() error { return ErrSpecific }

// ✅ 推荐：提供 Is/As 方法，隐藏实现细节
type DBError struct{ Msg string }
func (e *DBError) Error() string { return e.Msg }
func (e *DBError) Is(target error) bool {
    _, ok := target.(*DBError)
    return ok
}
错误处理最佳实践
1. 尽早处理
// ❌ 延迟处理
data, _ := ioutil.ReadFile(path)  // 忽略错误
result, _ := process(data)

// ✅ 尽早处理
data, err := os.ReadFile(path)
if err != nil {
    return fmt.Errorf(&quot;read: %w&quot;, err)
}
2. 只处理一次
// ❌ 重复处理：既 log 又返回
func Get() error {
    data, err := fetch()
    if err != nil {
        log.Printf(&quot;fetch failed: %v&quot;, err)  // log
        return err                           // 又返回
    }
    // ...
}

// ✅ 要么 log 要么 return，不要两者都做
func Get() error {
    data, err := fetch()
    if err != nil {
        return fmt.Errorf(&quot;fetch: %w&quot;, err)  // 让上层决定怎么处理
    }
    // ...
}
3. 用类型表达可选值
// ❌ 用 error 表达&quot;没有找到&quot;
user, err := findUser(id)
if errors.Is(err, ErrNotFound) { ... }

// ✅ 用 bool 或指针 nil 表达
user, found := findUser(id)
if !found { ... }

// ✅ 或返回 *User，nil 表示不存在
user, err := findUser(id)
if user == nil { ... }
panic 的适用场景
// panic 只用在&quot;不可能发生&quot;的错误
// 1. 程序初始化失败
func init() {
    if err := loadConfig(); err != nil {
        panic(err)  // 配置错误应该直接崩溃
    }
}

// 2. 接口契约被违反
func (s *Stack) Pop() interface{} {
    if s.Empty() {
        panic(&quot;stack: Pop called on empty stack&quot;)
    }
    // ...
}
参考资料

Go Blog: Error handling and Go
Go Blog: Errors are values
Go 1.13: Working with Errors
Dave Cheney: Don’t just check errors, handle them gracefully

golang/进阶/go-进阶-13---日志处理-log-slog.content:
Go 进阶 13 — 日志处理 log/slog
slog 简介
Go 1.21+ 标准库引入了 log/slog — 结构化日志库：
import &quot;log/slog&quot;

slog.Info(&quot;server started&quot;, &quot;port&quot;, 8080, &quot;env&quot;, &quot;production&quot;)
// 2024/01/15 10:30:00 INFO server started port=8080 env=production

























日志级别说明slog.Debug调试信息slog.Info一般信息slog.Warn警告slog.Error错误
结构化日志
键值对方式
slog.Info(&quot;request processed&quot;,
    &quot;method&quot;, r.Method,
    &quot;path&quot;, r.URL.Path,
    &quot;status&quot;, resp.StatusCode,
    &quot;duration&quot;, time.Since(start),
)
分组
slog.Info(&quot;user action&quot;,
    &quot;user&quot;, slog.Group(&quot;user&quot;, &quot;id&quot;, 123, &quot;role&quot;, &quot;admin&quot;),
    &quot;action&quot;, &quot;login&quot;,
)
// 输出：user.id=123 user.role=admin action=login
Attr 方式
slog.LogAttrs(context.Background(), slog.LevelInfo,
    &quot;request completed&quot;,
    slog.String(&quot;method&quot;, &quot;GET&quot;),
    slog.Int(&quot;status&quot;, 200),
    slog.Duration(&quot;duration&quot;, 150*time.Millisecond),
    slog.Any(&quot;error&quot;, err),
)
Logger 配置
创建 Logger
// Text 格式（默认）
logger := slog.New(slog.NewTextHandler(os.Stdout, nil))

// JSON 格式（推荐生产环境）
logger := slog.New(slog.NewJSONHandler(os.Stdout, nil))
// {&quot;time&quot;:&quot;2024-01-15T10:30:00Z&quot;,&quot;level&quot;:&quot;INFO&quot;,&quot;msg&quot;:&quot;server started&quot;,&quot;port&quot;:8080}

// 配置文件
handler := slog.NewJSONHandler(os.Stdout, &amp;slog.HandlerOptions{
    Level:     slog.LevelWarn,       // 只输出 Warn 及以上
    AddSource: true,                  // 添加源代码位置
})
logger := slog.New(handler)
设置为全局 logger
slog.SetDefault(logger)
// 现在 slog.Info() 会使用自定义 logger
slog.Info(&quot;this uses json format&quot;)
自定义 Handler
type RedactedHandler struct {
    handler slog.Handler
}

func (h *RedactedHandler) Handle(ctx context.Context, r slog.Record) error {
    // 修改记录：隐藏密码字段
    r.Attrs(func(a slog.Attr) {
        if a.Key == &quot;password&quot; {
            r.AddAttrs(slog.String(&quot;password&quot;, &quot;***&quot;))
        }
    })
    return h.handler.Handle(ctx, r)
}

func (h *RedactedHandler) Enabled(ctx context.Context, level slog.Level) bool {
    return h.handler.Enabled(ctx, level)
}

func (h *RedactedHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
    return &amp;RedactedHandler{h.handler.WithAttrs(attrs)}
}

func (h *RedactedHandler) WithGroup(name string) slog.Handler {
    return &amp;RedactedHandler{h.handler.WithGroup(name)}
}
旧版 log 包
import &quot;log&quot;

// 基本用法
log.Println(&quot;server started on :8080&quot;)  // 2024/01/15 10:30:00 server started on :8080
log.Printf(&quot;user %s logged in&quot;, &quot;alice&quot;)

// 配置
log.SetFlags(log.Ldate | log.Ltime | log.Lshortfile)
log.SetPrefix(&quot;[myapp] &quot;)
log.SetOutput(os.Stderr)
日志最佳实践
1. 统一日志格式
// 项目启动时配置
func init() {
    handler := slog.NewJSONHandler(os.Stderr, &amp;slog.HandlerOptions{
        Level: slog.LevelInfo,
    })
    slog.SetDefault(slog.New(handler))
}
2. 日志信息要有上下文
// ❌ 不好：没有上下文
slog.Error(&quot;error&quot;)

// ✅ 好：包含操作、资源、错误信息
slog.Error(&quot;failed to fetch user&quot;,
    &quot;user_id&quot;, id,
    &quot;error&quot;, err,
)
3. 不要 log 敏感信息
// ❌ 不要记录密码、token
slog.Info(&quot;user login&quot;, &quot;password&quot;, pwd)

// ✅ 记录脱敏信息
slog.Info(&quot;user login&quot;, &quot;user_id&quot;, id, &quot;ip&quot;, ip)
4. 使用 RequestID 串联请求
// 在中间件中设置
ctx = context.WithValue(ctx, &quot;request_id&quot;, requestID)
logger := slog.With(&quot;request_id&quot;, requestID)
slog.SetDefault(logger)
参考资料

log/slog 官方文档
Go Blog: Structured Logging with slog
slog 使用指南

golang/进阶/go-进阶-14---http服务开发.content:
Go 进阶 14 — HTTP 服务开发
标准库 net/http
import &quot;net/http&quot;

// 基本 HTTP 服务器
func main() {
    http.HandleFunc(&quot;/hello&quot;, func(w http.ResponseWriter, r *http.Request) {
        fmt.Fprintf(w, &quot;Hello, %s!&quot;, r.URL.Query().Get(&quot;name&quot;))
    })

    log.Fatal(http.ListenAndServe(&quot;:8080&quot;, nil))
}
Handler 接口
type Handler interface {
    ServeHTTP(w http.ResponseWriter, r *http.Request)
}

// 自定义 Handler
type HelloHandler struct{}

func (h *HelloHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
    w.Write([]byte(&quot;Hello, World!&quot;))
}

http.Handle(&quot;/hello&quot;, &amp;HelloHandler{})
请求处理
获取请求信息
func handler(w http.ResponseWriter, r *http.Request) {
    // 方法
    fmt.Println(r.Method)           // GET, POST, PUT...
    fmt.Println(r.URL.Path)         // /api/users/123

    // 查询参数
    name := r.URL.Query().Get(&quot;name&quot;)
    page, _ := strconv.Atoi(r.URL.Query().Get(&quot;page&quot;))

    // Header
    contentType := r.Header.Get(&quot;Content-Type&quot;)
    token := r.Header.Get(&quot;Authorization&quot;)

    // Body
    body, err := io.ReadAll(r.Body)
    defer r.Body.Close()

    // Cookie
    cookie, err := r.Cookie(&quot;session_id&quot;)

    // 表单
    r.ParseForm()
    username := r.Form.Get(&quot;username&quot;)
}
响应
func response(w http.ResponseWriter, r *http.Request) {
    // 状态码
    w.WriteHeader(http.StatusOK)    // 200
    w.WriteHeader(http.StatusNotFound)  // 404
    w.WriteHeader(http.StatusInternalServerError)  // 500

    // 响应体
    w.Write([]byte(&quot;OK&quot;))

    // Header
    w.Header().Set(&quot;Content-Type&quot;, &quot;application/json&quot;)
    w.Header().Set(&quot;X-Request-ID&quot;, requestID)

    // JSON 响应
    w.Header().Set(&quot;Content-Type&quot;, &quot;application/json&quot;)
    json.NewEncoder(w).Encode(map[string]interface{}{
        &quot;status&quot;: &quot;ok&quot;,
        &quot;data&quot;:   result,
    })
}
路由
Go 1.22+ 标准库支持路径参数和方法路由：
// Go 1.22+ 路由增强
mux := http.NewServeMux()
mux.HandleFunc(&quot;GET /api/users/{id}&quot;, getUser)
mux.HandleFunc(&quot;POST /api/users&quot;, createUser)
mux.HandleFunc(&quot;DELETE /api/users/{id}&quot;, deleteUser)

func getUser(w http.ResponseWriter, r *http.Request) {
    id := r.PathValue(&quot;id&quot;)   // 路径参数
    // ...
}
第三方路由
import &quot;github.com/go-chi/chi/v5&quot;

r := chi.NewRouter()
r.Get(&quot;/api/users/{id}&quot;, getUser)
r.Post(&quot;/api/users&quot;, createUser)
r.Put(&quot;/api/users/{id}&quot;, updateUser)
r.Delete(&quot;/api/users/{id}&quot;, deleteUser)

// 路由组
r.Route(&quot;/api&quot;, func(r chi.Router) {
    r.Use(AuthMiddleware)
    r.Get(&quot;/users&quot;, listUsers)
    r.Get(&quot;/users/{id}&quot;, getUser)
})
中间件模式
// 标准库中间件
func loggingMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        start := time.Now()
        next.ServeHTTP(w, r)
        slog.Info(&quot;request&quot;,
            &quot;method&quot;, r.Method,
            &quot;path&quot;, r.URL.Path,
            &quot;duration&quot;, time.Since(start),
        )
    })
}

// 链式中间件
handler := loggingMiddleware(authMiddleware(http.HandlerFunc(handler)))
常用中间件
// CORS
func corsMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set(&quot;Access-Control-Allow-Origin&quot;, &quot;*&quot;)
        w.Header().Set(&quot;Access-Control-Allow-Methods&quot;, &quot;GET, POST, PUT, DELETE&quot;)
        w.Header().Set(&quot;Access-Control-Allow-Headers&quot;, &quot;Content-Type, Authorization&quot;)
        if r.Method == &quot;OPTIONS&quot; {
            w.WriteHeader(204)
            return
        }
        next.ServeHTTP(w, r)
    })
}

// Recovery
func recoveryMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        defer func() {
            if err := recover(); err != nil {
                log.Printf(&quot;panic recovered: %v&quot;, err)
                http.Error(w, &quot;Internal Server Error&quot;, 500)
            }
        }()
        next.ServeHTTP(w, r)
    })
}
优雅关闭
func main() {
    srv := &amp;http.Server{
        Addr:    &quot;:8080&quot;,
        Handler: mux,
    }

    // 启动服务器
    go func() {
        slog.Info(&quot;server starting on :8080&quot;)
        if err := srv.ListenAndServe(); err != nil &amp;&amp; err != http.ErrServerClosed {
            log.Fatal(err)
        }
    }()

    // 等待信号
    quit := make(chan os.Signal, 1)
    signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
    &lt;-quit
    slog.Info(&quot;shutting down server...&quot;)

    // 优雅关闭（最多等待 30 秒）
    ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
    defer cancel()

    if err := srv.Shutdown(ctx); err != nil {
        log.Fatal(&quot;server forced to shutdown:&quot;, err)
    }
    slog.Info(&quot;server exited&quot;)
}
超时设置
srv := &amp;http.Server{
    Addr:         &quot;:8080&quot;,
    Handler:      mux,
    ReadTimeout:  10 * time.Second,   // 读取请求超时
    WriteTimeout: 10 * time.Second,   // 写入响应超时
    IdleTimeout:  60 * time.Second,   // 长连接空闲超时
}
