Go Interview 06
go两个协程交替打印1-100的奇数偶数
package main

import (
	&quot;fmt&quot;
	&quot;time&quot;
)

const Pool = 100

func goroutine1(msg chan int) {
	for i:=1; i&lt;=Pool; i++ {
		msg &lt;- i
		if i%2 == 1 {
			fmt.Println(&quot;goroutine1:&quot;, i)
		}
	}
}

func goroutine2(msg chan int) {
	for i := 1; i &lt;= Pool; i++ {
		&lt;- msg
		if i%2 == 0 {
			fmt.Println(&quot;goroutine2:&quot;, i)
		}
	}
}

func main() {
	msg := make(chan int)
	go goroutine1(msg)
	go goroutine2(msg)
	time.Sleep(time.Second)
}

golang/面试/go-面试-07.content:
Go Interview 07
Go互斥锁的两种实现
1.用Mutex实现
package main

import (
	&quot;fmt&quot;
	&quot;sync&quot;
)

var num int
var mtx sync.Mutex
var wg sync.WaitGroup

func add() {
	//mutex锁住
	mtx.Lock()
	//mutex解锁
	defer mtx.Unlock()
	//wg计数器减一
	defer wg.Done()

	num += 1
}

func main() {
	for i := 0; i &lt; 100; i++ {
		wg.Add(1)
		go add()
	}

	//wg.wait代替了之前的time.sleep。wg里面相当于有个计数器，只有计数器没了才继续进行，否则就阻塞。
	wg.Wait()
	fmt.Println(num)
}

使用chan实现

package main

import (
	&quot;fmt&quot;
	&quot;sync&quot;
)

var num int

func add(h chan int, wg *sync.WaitGroup)  {
	defer wg.Done()
	h &lt;- 1
	num += 1
	&lt;-h
}

func main() {
	var wg = &amp;sync.WaitGroup{}
	h := make(chan int, 1)
	for i := 0; i &lt; 100; i++ {
		wg.Add(1)
		go add(h, wg)
	}
	wg.Wait()
	fmt.Println(num)
}

golang/面试/go-面试-08.content:
Go Interview 08
什么是map
map是一个可以存储key/value对的一种数据结构，map像slice一样是引用类型，map内部实现是一个hash table，因此在map中存入数据是无序的。而每次从map中读取数据也是无序的，因为在golang设计之初，map迭代器的顺序就是随机的，有别于C/C++，虽然存入map的数据是无序的，但是每次从map中取出的数据一样的。
声明和初始化
// 声明一个map，因为map是引用类型，所以m是nil
var m map[keytype]valuetype

// 初始化方式1，空map，空并不是nil
m := map[keytype]valuetype{}

// 初始化方式2，两种初始化方式相同
m := make(make[keytype]valuetype)
基本操作
package main

import &quot;fmt&quot;

func main() {
	m := map[string]int{}

	//增加一个map
	m[&quot;tony&quot;] = 10

	//删除一个key = tony的map
	delete(m, &quot;tony&quot;)

	//修改key=tony的值
	m[&quot;tony&quot;] = 20

	//判断某个key是否存在
	if _, ok := m[&quot;tony&quot;]; ok {
		fmt.Println(&quot;tony is exists&quot;)
	}

	//遍历map
	for key, value := range m {
		fmt.Println(key, value)
	}

	//使用多个值对map进行初始化
	m1 := map[string]int{
		&quot;Tina&quot;: 10,
		&quot;Dviad&quot;: 20,
		&quot;Tom&quot;: 5,
	}
	fmt.Println(m1)
}
key和value可以使用什么类型
key：只要是可比较(可以使用==进行比较，两边的操作数可以互相赋值)的类型就可以，像整型，字符串类型，浮点型，数组(必须类型相同)；而map，slice和function不能作为key的类型
value：任何类型都可以
对map进行并发访问时需要增加同步机制
map在并发访问中使用不安全，因为不清楚当时对map进行读写的时候会发生什么，如果像通过goroutine进行并发访问，则需要一种同步机制来保证访问数据的安全性。一种方法是使用sync.RWMutex
//通过匿名函数结构体声明一个counter，变量中包含map和sync.RWMutex
	var counter = struct {
		sync.RWMutex
		m map[string]int
	}{m: make(map[string]int)}

	//读取数据的时候使用读锁
	counter.RLock()
	n := counter.m[&quot;Tony&quot;]
	counter.RUnlock()
	fmt.Println(n)

	//写数据的时候使用写锁
	counter.Lock()
	counter.m[&quot;Tony&quot;]++
	counter.Unlock()
	fmt.Println(counter.m[&quot;Tony&quot;])

java/io/java-13---file与io流.content:
Java 13 - File与IO流
File 类
java.io.File 表示文件或目录路径的抽象表示。
File file = new File(&quot;/path/to/file.txt&quot;);
file.exists();       // 是否存在
file.isFile();       // 是否文件
file.isDirectory();  // 是否目录
file.getName();      // 文件名
file.length();       // 文件大小
file.mkdirs();       // 创建目录
file.createNewFile(); // 创建文件
file.delete();       // 删除
IO 流分类
按流向：

输入流 — 读取数据（读入内存）
输出流 — 写入数据（写出到目的地）

按数据类型：

字节流 — 处理二进制文件（图片、视频等）
字符流 — 处理文本文件（.txt、.java 等）

字节流























抽象类输入输出说明InputStreamFileInputStreamFileOutputStream文件字节流BufferedInputStreamBufferedInputStreamBufferedOutputStream缓冲字节流
// 文件复制：字节流
try (FileInputStream fis = new FileInputStream(&quot;src.jpg&quot;);
     FileOutputStream fos = new FileOutputStream(&quot;dest.jpg&quot;)) {
    byte[] buffer = new byte[1024];
    int len;
    while ((len = fis.read(buffer)) != -1) {
        fos.write(buffer, 0, len);
    }
}
字符流



































抽象类输入输出说明ReaderFileReaderFileWriter文件字符流BufferedReaderBufferedReaderBufferedWriter缓冲字符流InputStreamReader字节→字符转换—解码OutputStreamWriter—字符→字节转换编码
// 文本读取：字符流（推荐）
try (BufferedReader br = new BufferedReader(new FileReader(&quot;input.txt&quot;))) {
    String line;
    while ((line = br.readLine()) != null) {
        System.out.println(line);
    }
}
try-with-resources (Java 7+)
自动关闭实现了 AutoCloseable 的资源：
try (FileInputStream fis = new FileInputStream(&quot;file.txt&quot;)) {
    // 使用 fis
}  // 自动调用 fis.close()
序列化与 transient

Serializable 接口 — 标记对象可序列化
transient — 修饰的字段不参与序列化

public class User implements Serializable {
    private static final long serialVersionUID = 1L;
    private String name;
    private transient String password;  // 不序列化
}

java/io/java-14---nio与序列化.content:
Java 14 - NIO与序列化
NIO (New IO, Java 1.4+)
Java NIO 是面向缓冲区 (Buffer) 和通道 (Channel) 的 IO 模型。
核心组件





















组件说明Channel双向通道，可读可写：FileChannel、SocketChannel、ServerSocketChannelBuffer数据容器：ByteBuffer、CharBuffer、IntBufferSelector多路复用器，单线程管理多个 Channel
核心优势

非阻塞 IO — 线程不会在 read/write 上阻塞
零拷贝 — FileChannel.transferTo() 避免数据在用户态/内核态之间拷贝
内存映射文件 — MappedByteBuffer 可直接操作文件映射到内存的数据

Buffer 常用操作
ByteBuffer buffer = ByteBuffer.allocate(1024);
buffer.put(data);     // 写入数据
buffer.flip();        // 切换为读模式
buffer.get();         // 读取数据
buffer.clear();       // 清空缓冲区
buffer.rewind();      // 重读
FileChannel 示例
try (FileChannel in = FileChannel.open(Paths.get(&quot;src.txt&quot;), StandardOpenOption.READ);
     FileChannel out = FileChannel.open(Paths.get(&quot;dest.txt&quot;), 
         StandardOpenOption.CREATE, StandardOpenOption.WRITE)) {
    in.transferTo(0, in.size(), out);  // 零拷贝传输
}
Selector 多路复用
Selector selector = Selector.open();
channel.configureBlocking(false);
channel.register(selector, SelectionKey.OP_READ);

while (true) {
    selector.select();  // 阻塞直到有事件
    Set&lt;SelectionKey&gt; keys = selector.selectedKeys();
    for (SelectionKey key : keys) {
        if (key.isReadable()) { /* 读取 */ }
        if (key.isWritable()) { /* 写入 */ }
    }
    keys.clear();
}
序列化
Serializable 接口
public class User implements Serializable {
    private static final long serialVersionUID = 1L;
    private String name;
    private int age;
}
序列化与反序列化
// 序列化
try (ObjectOutputStream oos = new ObjectOutputStream(
        new FileOutputStream(&quot;user.ser&quot;))) {
    oos.writeObject(new User(&quot;Alice&quot;, 25));
}

// 反序列化
try (ObjectInputStream ois = new ObjectInputStream(
        new FileInputStream(&quot;user.ser&quot;))) {
    User user = (User) ois.readObject();
}
serialVersionUID

用于版本控制，确保序列化和反序列化使用同一个类版本
不显式声明则 JVM 自动生成，但类修改后自动生成值会变化
建议显式声明 private static final long serialVersionUID = 1L;

java/jvm/java-18---类加载机制.content:
Java 18 - 类加载机制
类加载生命周期
加载 → 验证 → 准备 → 解析 → 初始化 → 使用 → 卸载
          ↕ (可重排序)
        连接






























阶段说明加载通过全限定名获取二进制字节流，生成 Class 对象验证校验字节码合法性（格式、语义、符号引用）准备为静态变量分配内存并赋零值解析符号引用 → 直接引用初始化执行 &lt;clinit&gt;() 方法，为静态变量赋值
类加载器
┌─────────────────────────────────────┐
│          Bootstrap ClassLoader      │
│  (C++实现，加载 rt.jar / java.*)     │
├─────────────────────────────────────┤
│         Extension ClassLoader        │
│  (加载 jre/lib/ext/*.jar)           │
├─────────────────────────────────────┤
│         Application ClassLoader      │
│  (加载 classpath 下的类)             │
├─────────────────────────────────────┤
│         自定义 ClassLoader           │
│  (热部署、加密解密等场景)             │
└─────────────────────────────────────┘

双亲委派模型
工作流程

类加载器收到类加载请求
委派给父加载器尝试加载
父加载器无法加载（找不到此类）时，子加载器才尝试加载

protected Class&lt;?&gt; loadClass(String name) {
    // 1. 检查是否已加载
    Class&lt;?&gt; c = findLoadedClass(name);
    if (c == null) {
        if (parent != null) {
            c = parent.loadClass(name);  // 委派给父加载器
        } else {
            c = findBootstrapClassOrNull(name);
        }
    }
    // 2. 父加载器未找到，自己加载
    if (c == null) {
        c = findClass(name);
    }
    return c;
}
为什么用双亲委派？

安全性 — 防止核心 API 被篡改（java.lang.String 始终由 Bootstrap 加载器加载）
避免重复加载 — 父加载器已加载的子加载器无需再次加载

打破双亲委派

SPI (Service Provider Interface) — JDBC、JNDI 等使用线程上下文类加载器
热部署 — Tomcat 的 WebAppClassLoader 优先加载 web 应用中的类
OSGi — 每个模块有自己的类加载器

自定义 ClassLoader
public class MyClassLoader extends ClassLoader {
    @Override
    protected Class&lt;?&gt; findClass(String name) {
        byte[] bytes = loadClassData(name);
        return defineClass(name, bytes, 0, bytes.length);
    }
}

java/基础/java-05---运算符与流程控制.content:
Java 05 - 运算符与流程控制
运算符分类
算术运算符






























